import { MAX_TERAS_PER_ARENA } from "#app/constants";
import { globalScene } from "#app/global-scene";
import { showBattleInfoForActorOnly } from "#data/systems/mod-battle-info";
import { setP5XTurnOrderFocus } from "#data/systems/p5x-turn-order";
import { getTypeRgb } from "#data/type";
import { Button } from "#enums/buttons";
import { Command } from "#enums/command";
import { PokemonType } from "#enums/pokemon-type";
import { TextStyle } from "#enums/text-style";
import { UiMode } from "#enums/ui-mode";
import { CommandPhase } from "#phases/command-phase";
import { SwitchSummonPhase } from "#phases/switch-summon-phase";
import { SwitchType } from "#enums/switch-type";
import { PartyUiHandler, PartyUiMode } from "#ui/party-ui-handler";
import { addTextObject } from "#ui/text";
import { UiHandler } from "#ui/ui-handler";
import { canEnterCallingCardTurnFor } from "#data/systems/callingcard-system";
import { HealerWishPhase, consumeHealerWish, healerWishReady } from "#data/systems/healer-system";
import { debugLog } from "#data/systems/mod-utils";
import { getJiemingButtonState } from "#data/systems/jieming-system";
import { getSuperBackpackManager } from "#data/systems/mod-super-backpack";
import { canTerastallize } from "#utils/pokemon-utils";
import i18next from "i18next";

export class CommandUiHandler extends UiHandler {
  private commandsContainer: Phaser.GameObjects.Container;
  private cursorObj: Phaser.GameObjects.Image | null;

  private teraButton: Phaser.GameObjects.Sprite;

  protected fieldIndex = 0;
  protected cursor2 = 0;

  constructor() {
    super(UiMode.COMMAND);
  }

  setup() {
    const ui = this.getUi();
    const commands = [
      i18next.t("commandUiHandler:fight"),
      i18next.t("commandUiHandler:ball"),
      i18next.t("commandUiHandler:pokemon"),
      i18next.t("commandUiHandler:run"),
    ];

    this.commandsContainer = globalScene.add.container(217, -38.7);
    this.commandsContainer.setName("commands");
    this.commandsContainer.setVisible(false);
    ui.add(this.commandsContainer);

    this.teraButton = globalScene.add.sprite(-32, 15, "button_tera");
    this.teraButton.setName("terastallize-button");
    this.teraButton.setScale(1.3);
    this.teraButton.setFrame("fire");
    this.teraButton.setPipeline(globalScene.spritePipeline, {
      tone: [0.0, 0.0, 0.0, 0.0],
      ignoreTimeTint: true,
      teraColor: getTypeRgb(PokemonType.FIRE),
      isTerastallized: false,
    });
    this.commandsContainer.add(this.teraButton);

    for (let c = 0; c < commands.length; c++) {
      const commandText = addTextObject(
        c % 2 === 0 ? 0 : 55.8,
        c < 2 ? 0 : 16,
        commands[c],
        TextStyle.WINDOW_BATTLE_COMMAND,
      );
      commandText.setName(commands[c]);
      this.commandsContainer.add(commandText);
    }
  }

  show(args: any[]): boolean {
    super.show(args);

    this.fieldIndex = args.length > 0 ? (args[0] as number) : 0;

    this.commandsContainer.setVisible(true);

    let commandPhase: CommandPhase;
    const currentPhase = globalScene.phaseManager.getCurrentPhase();
    if (currentPhase.is("CommandPhase")) {
      commandPhase = currentPhase;
    } else {
      commandPhase = globalScene.phaseManager.getStandbyPhase() as CommandPhase;
    }

    if (this.canTera()) {
      this.teraButton.setVisible(true);
      this.teraButton.setFrame(PokemonType[globalScene.getField()[this.fieldIndex].getTeraType()].toLowerCase());
    } else {
      this.teraButton.setVisible(false);
      if (this.getCursor() === Command.TERA) {
        this.setCursor(Command.FIGHT);
      }
    }
    this.toggleTeraButton();

    const pokemonName = commandPhase.getPokemon().getNameToRender({ prependFormName: false });
    const messageHandler = this.getUi().getMessageHandler();
    messageHandler.bg.setVisible(true);
    messageHandler.commandWindow.setVisible(true);
    messageHandler.movesWindowContainer.setVisible(false);
    messageHandler.message.setWordWrapWidth(this.canTera() ? 910 : 1110);
    messageHandler.showText(i18next.t("commandUiHandler:actionMessage", { pokemonName }), 0);

    if (this.getCursor() === Command.POKEMON) {
      this.setCursor(Command.FIGHT);
    } else {
      this.setCursor(this.getCursor());
    }

    return true;
  }

  processInput(button: Button): boolean {
    const ui = this.getUi();

    let success = false;

    const cursor = this.getCursor();

    if (button === Button.CANCEL || button === Button.ACTION) {
      if (button === Button.ACTION) {
        switch (cursor) {
          // Fight
          case Command.FIGHT:
            ui.setMode(UiMode.FIGHT, (globalScene.phaseManager.getCurrentPhase() as CommandPhase).getFieldIndex());
            success = true;
            break;
          // Ball
          case Command.BALL:
            ui.setModeWithoutClear(UiMode.BALL);
            success = true;
            break;
          // Pokemon
          case Command.POKEMON:
            ui.setMode(
              UiMode.PARTY,
              PartyUiMode.SWITCH,
              (globalScene.phaseManager.getCurrentPhase() as CommandPhase).getPokemon().getFieldIndex(),
              null,
              PartyUiHandler.FilterNonFainted,
            );
            success = true;
            break;
          // Run
          case Command.RUN:
            (globalScene.phaseManager.getCurrentPhase() as CommandPhase).handleCommand(Command.RUN, 0);
            success = true;
            break;
          case Command.TERA:
            ui.setMode(
              UiMode.FIGHT,
              (globalScene.phaseManager.getCurrentPhase() as CommandPhase).getFieldIndex(),
              Command.TERA,
            );
            success = true;
            break;
          // ▼▼▼ PKRC 魔改 patch: [healer] 【祈愿】分发（产物 `case As.WISH: r=this.handleWishCommand()`）▲▲▲
          case Command.WISH:
            success = this.handleWishCommand();
            break;
          // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲
        }
      } else {
        (globalScene.phaseManager.getCurrentPhase() as CommandPhase).cancel();
      }
    } else {
      switch (button) {
        case Button.UP:
          if (cursor === Command.POKEMON || cursor === Command.RUN) {
            success = this.setCursor(cursor - 2);
          }
          break;
        case Button.DOWN:
          if (cursor === Command.FIGHT || cursor === Command.BALL) {
            success = this.setCursor(cursor + 2);
          }
          break;
        case Button.LEFT:
          if (cursor === Command.BALL || cursor === Command.RUN) {
            success = this.setCursor(cursor - 1);
          } else if ((cursor === Command.FIGHT || cursor === Command.POKEMON) && this.canTera()) {
            success = this.setCursor(Command.TERA);
            this.toggleTeraButton();
          }
          break;
        case Button.RIGHT:
          if (cursor === Command.FIGHT || cursor === Command.POKEMON) {
            success = this.setCursor(cursor + 1);
          } else if (cursor === Command.TERA) {
            success = this.setCursor(Command.FIGHT);
            this.toggleTeraButton();
          }
          break;
      }
    }

    if (success) {
      ui.playSelect();
    }

    return success;
  }

  canTera(): boolean {
    const activePokemon = globalScene.getField()[this.fieldIndex];
    const currentTeras = globalScene.arena.playerTerasUsed;
    const canTera = activePokemon.isPlayer() && canTerastallize(activePokemon);
    const plannedTera = +(
      globalScene.currentBattle.preTurnCommands[0]?.command === Command.TERA && this.fieldIndex > 0
    );
    return canTera && currentTeras + plannedTera < MAX_TERAS_PER_ARENA;
  }

  toggleTeraButton() {
    this.teraButton.setPipeline(globalScene.spritePipeline, {
      tone: [0.0, 0.0, 0.0, 0.0],
      ignoreTimeTint: true,
      teraColor: getTypeRgb(globalScene.getField()[this.fieldIndex].getTeraType()),
      isTerastallized: this.getCursor() === Command.TERA,
    });
  }

  getCursor(): number {
    return this.fieldIndex ? this.cursor2 : this.cursor;
  }

  setCursor(cursor: number): boolean {
    const changed = this.getCursor() !== cursor;
    if (changed) {
      if (this.fieldIndex) {
        this.cursor2 = cursor;
      } else {
        this.cursor = cursor;
      }
    }

    if (!this.cursorObj) {
      this.cursorObj = globalScene.add.image(0, 0, "cursor");
      this.commandsContainer.add(this.cursorObj);
    }

    if (cursor === Command.TERA) {
      this.cursorObj.setVisible(false);
    } else {
      this.cursorObj.setPosition(-5 + (cursor % 2 === 1 ? 56 : 0), 8 + (cursor >= 2 ? 16 : 0));
      this.cursorObj.setVisible(true);
    }

    return changed;
  }

  clear(): void {
    super.clear();
    this.getUi().getMessageHandler().commandWindow.setVisible(false);
    this.commandsContainer.setVisible(false);
    this.getUi().getMessageHandler().clearText();
    // ▼▼▼ PKRC 魔改 patch: [P5X] 指令菜单关闭时恢复 battleInfo 显示 + 清顺序条焦点（产物 CommandUiHandler.clear 尾部 `MOe(E.getField()[this.fieldIndex]),fl(null)`）▲▲▲
    showBattleInfoForActorOnly(globalScene.getField()[this.fieldIndex]);
    setP5XTurnOrderFocus(null);
    // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲
    this.eraseCursor();
  }

  eraseCursor(): void {
    if (this.cursorObj) {
      this.cursorObj.destroy();
    }
    this.cursorObj = null;
  }

  // ▼▼▼ PKRC 魔改 patch: [squad] 命令可见性判断 + squad 命令列表（产物 CommandUiHandler 的 6 个 mod 方法）▲▲▲

  /** 产物 `isEryouMode()` — 是否处于 ERYOU（二游）模式 */
  isEryouMode(): boolean {
    return !!globalScene.gameMode?.isEryou;
  }

  /** 产物 `canCallingCard()` — 预告信命令可见（我方 + 预告信层数可进入预告信回合） */
  canCallingCard(): boolean {
    const pokemon = globalScene.getField()[this.fieldIndex];
    if (!pokemon || !pokemon.isPlayer()) {
      return false;
    }
    const callingCards = pokemon.customPokemonData?.callingCards ?? 0;
    return canEnterCallingCardTurnFor(pokemon, callingCards);
  }

  /** 产物 `canWish()` — 祈愿命令可见（healer 祈愿就绪） */
  canWish(): boolean {
    return healerWishReady(globalScene.getField()[this.fieldIndex]);
  }

  /** 产物 `hasJieming()` — 解明命令可见 */
  hasJieming(): boolean {
    return getJiemingButtonState().visible;
  }

  /**
   * 产物 `getSquadCommands()` — squad 命令列表（ERYOU 模式 4 项 / 常规 4 项 + 条件追加项）。
   * ⚠️ 产物 `FE().isActivated() && s.push({id:5,label:"背包"})`：FE=getSuperBackpackManager 未迁
   *   （挂账超级背包批）⇒ 背包命令暂不显示（超级背包迁入后补回）。
   */
  getSquadCommands(): SquadCommand[] {
    const commands: SquadCommand[] = this.isEryouMode()
      ? [
          { id: 0, label: "战斗" },
          { id: 1, label: "我方状态" },
          { id: 2, label: "队伍" },
          { id: 3, label: "敌方状态" },
        ]
      : [
          { id: 0, label: "战斗" },
          { id: 1, label: "精灵球" },
          { id: 2, label: "队伍" },
          { id: 3, label: "撤退" },
        ];
    if (this.canTera()) {
      commands.push({ id: 4, label: "太晶化" });
    }
    if (getSuperBackpackManager().isActivated()) {
      commands.push({ id: 5, label: "背包" });
    }
    if (this.canCallingCard()) {
      commands.push({ id: 6, label: "预告信" });
    }
    if (this.canWish()) {
      commands.push({ id: 8, label: "祈愿" });
    }
    if (this.hasJieming()) {
      commands.push({ id: 7, label: "解明" });
    }
    return commands;
  }

  /** 产物 `activateSquadCommand(id)` — 激活 squad 命令（仅在 COMMAND 模式且命令存在时） */
  activateSquadCommand(id: number): boolean {
    if (this.getUi().getMode() !== UiMode.COMMAND || !this.getSquadCommands().some((c) => c.id === id)) {
      return false;
    }
    this.setCursor(id);
    return this.processInput(Button.ACTION);
  }

  // ▼▼▼ PKRC 魔改 patch: [healer] 【祈愿】命令（产物 `handleWishCommand`，@2166145，934 字符）▲▲▲
  /**
   * 产物 `handleWishCommand()` — 消耗【生机】发动【祈愿】：打开队友选择界面复活濒死队友。
   * 产物用 `await GR(()=>import(...))` 动态拿 `SwitchSummonPhase`（懒加载 chunk）；
   * 新树该 Phase 是静态可用的上游类 ⇒ 直接 import，**去掉动态 import 链**（语义等价）。
   */
  handleWishCommand(): boolean {
    const pokemon = globalScene.getPlayerField()[this.fieldIndex];
    if (!pokemon || !healerWishReady(pokemon)) {
      return false;
    }
    const cost = consumeHealerWish(pokemon);
    if (cost <= 0) {
      return false;
    }
    debugLog("healer", `[生命的余响] ${pokemon.name} 消耗 ${cost} 层【生机】发动【祈愿】`);
    const fieldIndex = this.fieldIndex;
    globalScene.phaseManager.unshiftPhase(
      new HealerWishPhase(pokemon, {
        openAllySelect: (healer: any, onPicked: (ally: any) => void) => {
          this.getUi().setMode(
            UiMode.PARTY,
            PartyUiMode.REVIVAL_BLESSING,
            healer.getFieldIndex(),
            (selected: any) => {
              this.getUi().setMode(UiMode.MESSAGE).then(() => onPicked(selected));
            },
            PartyUiHandler.FilterFainted,
          );
        },
        reopenCommand: () => {
          globalScene.phaseManager.unshiftPhase(new CommandPhase(fieldIndex));
        },
        sendOutRevivedAlly: async (ally: any) => {
          const party = globalScene.getPlayerParty();
          const slotIndex = party.findIndex((p) => p.id === ally.id);
          const battlerCount = globalScene.currentBattle?.getBattlerCount() ?? 1;
          if (slotIndex < 0 || slotIndex >= battlerCount || ally.isOnField()) {
            return;
          }
          debugLog(
            "healer",
            `[生命的余响] 【祈愿】复活后立即上场：${ally.name}（队伍第 ${slotIndex} 位）`,
          );
          globalScene.phaseManager.unshiftPhase(
            new SwitchSummonPhase(SwitchType.SWITCH, slotIndex, slotIndex, false, true),
          );
        },
      }),
    );
    return true;
  }
  // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲

  // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲
}

/** squad 命令项（产物 `getSquadCommands` 返回的元素） */
export interface SquadCommand {
  id: number;
  label: string;
}
