/** 当前信息视图（产物 `vN`）：none / field / player / enemy */
export type SquadInfoView = "none" | "field" | "player" | "enemy";

let infoViewMode: SquadInfoView = "none";
/** 状态面板模式（产物 `DR`）：仅 player / enemy 时激活 */
let statusPanelMode: "player" | "enemy" | null = null;
/** 状态面板当前页（产物 `UO`，0-based） */
let statusPage = 0;
/** 状态面板滚动偏移（产物 `BU`） */
let statusScroll = 0;
/** 解明冷却 provider（产物 `yM`，由 registerSquadJiemingCooldownProvider 注册） */
let jiemingCooldownProvider: (() => unknown) | null = null;

/** squad HUD 实例缓存（产物 `bse`，按 Ui 实例键） */
const squadHudCache = new WeakMap<object, SquadBattleHud>();

/** 消息字号候选（产物 `VIe`，applySquadBattleLayout 用） */
export const SQUAD_MESSAGE_FONT_SIZES = [34, 28, 24] as const;

// ─────────────────────────────────────────────────────────────
// 叶子函数
// ─────────────────────────────────────────────────────────────

/** 产物 `Whe` = fitLabelWidth — 设置文本，超出宽度则逐字截断加省略号 */
export function fitLabelWidth(
  text: Phaser.GameObjects.Text,
  content: string,
  maxWidth: number,
): void {
  text.setText(content);
  const chars = Array.from(content);
  while (text.displayWidth > maxWidth && chars.length > 1) {
    chars.pop();
    text.setText(chars.join("") + "…");
  }
}

/** 产物 `Yhe` = getSquadInfoView — 返回当前信息视图 */
export function getSquadInfoView(): SquadInfoView {
  return infoViewMode;
}

/** 产物 `bh` = setSquadInfoView — 设置信息视图（联动 arenaFlyout + 状态面板模式重置） */
export function setSquadInfoView(view: SquadInfoView): void {
  infoViewMode = view;
  globalScene.arenaFlyout?.toggleFlyout(view === "field");
  statusPanelMode = view === "player" || view === "enemy" ? view : null;
  statusPage = 0;
  statusScroll = 0;
}

/** 产物 `vhe` = cycleSquadInfoView — 循环切换信息视图，返回新视图 */
export function cycleSquadInfoView(): SquadInfoView {
  const next: SquadInfoView =
    infoViewMode === "none"
      ? "field"
      : infoViewMode === "field"
        ? "player"
        : infoViewMode === "player"
          ? "enemy"
          : "none";
  setSquadInfoView(next);
  return next;
}

/** 产物 `loe` = closeSquadStatusPanel — 关闭状态面板（切回 none） */
export function closeSquadStatusPanel(): void {
  setSquadInfoView("none");
}

/** 产物 `NB` = stepSquadStatusUnit — 状态面板翻页（delta ±1，钳到 ≥0） */
export function stepSquadStatusUnit(delta: number): void {
  if (statusPanelMode) {
    statusPage = Math.max(0, statusPage + delta);
    statusScroll = 0;
  }
}

/** 产物 `Khe` = supportCooldownReadout — 支援冷却读数 */
export function supportCooldownReadout(
  cooldown: { remaining: number[] } | null | undefined,
): { text: string; ready: boolean } {
  const remaining = cooldown?.remaining ?? [];
  if (!remaining.length) {
    return { text: "", ready: false };
  }
  const ready = remaining.some((t) => t <= 0);
  return { text: `${ready ? "可用" : "冷却"} ${remaining.join("/")}`, ready };
}

/** 产物 `Fhe` = currentJiemingCooldown — 读取当前解明冷却（provider 未注册返回 undefined） */
export function currentJiemingCooldown(): unknown {
  try {
    return jiemingCooldownProvider?.() ?? undefined;
  } catch {
    return undefined;
  }
}

/** 产物 `yhe` = registerSquadJiemingCooldownProvider — 注册解明冷却 provider */
export function registerSquadJiemingCooldownProvider(provider: (() => unknown) | null): void {
  jiemingCooldownProvider = provider;
}

