export function getSquadStatusPanelMode(): "player" | "enemy" | null {
  return statusPanelMode;
}

export function getSquadStatusPage(): number {
  return statusPage;
}

export function setSquadStatusPage(value: number): void {
  statusPage = value;
}

export function getSquadStatusScroll(): number {
  return statusScroll;
}

export function setSquadStatusScroll(value: number): void {
  statusScroll = value;
}

