/** 场地缩放（产物 `RH`） */
const SQUAD_FIELD_SCALE = 1 / 6;
/** 支援位图标缩放（产物 `Kse`） */
const SUPPORT_ICON_SCALE = 0.4;
/** 支援位图标 x（产物 `Hhe`） */
const SUPPORT_ICON_X = 12;
/** 支援位图标 y（产物 `phe`） */
const SUPPORT_ICON_Y = 139.5;
/** 支援位图标 y 偏移（产物 `ghe`） */
const SUPPORT_ICON_Y_OFFSET = 30;
/** 支援文本 x（产物 `Wse`） */
const SUPPORT_TEXT_X = 21;
/** 支援冷却 x（产物 `Yse`） */
const SUPPORT_COOLDOWN_X = 81;
/** 支援冷却就绪颜色（产物 `mhe`） */
const SUPPORT_COOLDOWN_READY_COLOR = "#7fd4ff";

/** 产物 `Phe` = allowedModes — squad HUD 适用的 UiMode 集合 */
function allowedModes(): UiMode[] {
  return [UiMode.MESSAGE, UiMode.COMMAND, UiMode.FIGHT, UiMode.TARGET_SELECT, UiMode.BALL, UiMode.JIEMING];
}

/**
 * 产物 `K2` = SquadBattleHud — boss 血条 + 命令按钮 + 支援位 + 状态面板 + 触摸按钮。
 * 挂载于 Ui 实例（`owner`），由 {@link updateSquadBattleHud} 每帧刷新。
 */
export class SquadBattleHud extends Phaser.GameObjects.Container {
  private readonly owner: UI;
  private panels = new Map<string, Phaser.GameObjects.NineSlice>();
  private commandCursors = new Map<number, Phaser.GameObjects.Image>();
  private bossText: Phaser.GameObjects.Text;
  private bossHp: Phaser.GameObjects.Text;
  private supportText: Phaser.GameObjects.Text;
  private supportCooldown: Phaser.GameObjects.Text;
  private teraIcon: Phaser.GameObjects.Sprite;
  private statusPanel: Phaser.GameObjects.Container | null;
  private statusPanelCols: Phaser.GameObjects.Text[];
  private statusPanelTitle: Phaser.GameObjects.Text | null;
  private statusPanelHint: Phaser.GameObjects.Text | null;
  private statusPanelSignature = "";
  private supportIcon: Phaser.GameObjects.Container | null;
  private supportIconFor: Pokemon | null;
  private units = new Map<number, SquadUnitCard>();
  private commandLabels = new Map<number, Phaser.GameObjects.Text>();
  private commandHits = new Map<number, Phaser.GameObjects.Zone>();
  private bossLevel: Phaser.GameObjects.Container | null;
  private bossLevelKey = "";
  private featuredBoss: EnemyPokemon | null;
  private bossPanel: SquadUnitPanel;
  private bossFill: Phaser.GameObjects.Image;
  private supportCursor: Phaser.GameObjects.Image;
  private background: Phaser.GameObjects.Graphics;

  constructor(owner: UI) {
    super(globalScene, 0, -180);
    this.owner = owner;
    this.bossText = label(0, 0, "", 40, TextStyle.BATTLE_INFO);
    this.bossHp = label(0, 0, "", 26, TextStyle.WINDOW_ALT);
    this.supportText = label(8.5, 136, "", 33);
    this.supportCooldown = label(0, 0, "", 33).setOrigin(1, 0);
    this.teraIcon = globalScene.add.sprite(0, 0, "button_tera").setScale(0.5).setVisible(false).setName("native-tera-icon");
    this.statusPanel = null;
    this.statusPanelCols = [];
    this.statusPanelTitle = null;
    this.statusPanelHint = null;
    this.supportIcon = null;
    this.supportIconFor = null;
    this.bossLevel = null;
    this.featuredBoss = null;
    this.setName("squad-battle-hud");
    this.background = globalScene.add.graphics();

    const rect = SQUAD_HEADER_RECT;
    this.bossPanel = new SquadUnitPanel("boss", rect.width, rect.height, 1, 0.6)
      .setPosition(rect.x, rect.y)
      .setName("native-boss-panel");
    this.bossFill = globalScene.add.image(0, 0, "overlay_hp_boss", "high").setOrigin(0).setName("native-boss-hp");
    this.supportCursor = globalScene.add.image(5, 139.5, "cursor").setOrigin(0, 0.5).setScale(0.45).setVisible(false).setName("native-support-cursor");
    this.add([
      this.bossPanel,
      this.bossFill,
      this.background,
      this.bossText,
      this.bossHp,
      this.supportText,
      this.supportCooldown,
      this.supportCursor,
      this.teraIcon,
    ]);

    const zone = globalScene.add.zone(rect.x, rect.y, rect.width, rect.height).setOrigin(0).setInteractive();
    zone.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, () => {
      if (this.featuredBoss && this.owner.getMode() === UiMode.TARGET_SELECT) {
        (this.owner.handlers[UiMode.TARGET_SELECT] as TargetSelectUiHandler).selectSquadTarget(this.featuredBoss);
      } else if (this.featuredBoss) {
        setP5XTurnOrderFocus(this.featuredBoss);
        this.owner.showTooltip(this.featuredBoss.getNameToRender(), squadDescribe(this.featuredBoss), true);
      }
    });
    this.add(zone);
  }

  refresh(): void {
    const visible = usesSquadHud(globalScene.gameMode)
      && allowedModes().includes(this.owner.getMode())
      && globalScene.getField(true).some((p) => p?.isOnField());

    this.setVisible(visible);
    if (!visible) {
      globalScene.fieldUI.getByName<Phaser.GameObjects.Container>("p5x-turn-order")?.setVisible(false);
      return;
    }

    const hudState = getP5XHudOrderState();
    const currentPhase = globalScene.phaseManager.getCurrentPhase();
    const phasePokemon = (currentPhase as { getPokemon?: () => Pokemon | undefined } | undefined)?.getPokemon?.();
    const focusedPokemon = phasePokemon ?? globalScene.getField()[hudState.order[0]];
    const playerParty = globalScene.getPlayerParty().slice(0, 4);
    const enemyField = globalScene.getEnemyField().filter((p) => p?.scene && p.isOnField());
    const all: Pokemon[] = [...playerParty, ...enemyField];
    const alive = new Set(all.map((p) => p.id));

    for (const [id, card] of this.units) {
      if (!alive.has(id)) {
        card.destroy();
        this.units.delete(id);
      }
    }
    this.background.clear();
    for (const panel of this.panels.values()) panel.setVisible(false);

    const messageText = globalScene.ui.getMessageHandler()?.message?.text ?? "";
    const messageLines = Math.max(1, messageText ? messageText.split("\n").length : 1);
    this.window("message", 85, 117, 140, Math.max(16, messageLines * 6 + 3));

    for (const pokemon of all) {
      let card = this.units.get(pokemon.id);
      if (card && card.pokemon !== pokemon) {
        card.destroy();
        this.units.delete(pokemon.id);
        card = undefined;
      }
      if (!card) {
        card = new SquadUnitCard(pokemon, pokemon.isPlayer());
        this.units.set(pokemon.id, card);
        this.add(card);
      }
      card.render(
        pokemon === focusedPokemon,
        pokemon.getBattlerIndex() === hudState.focus,
        playerParty.indexOf(pokemon as PlayerPokemon),
      );
      pokemon.getBattleInfo().setVisible(false);
    }

    const bosses = enemyField.filter((p) => p.isBoss());
    this.featuredBoss = bosses.find((p) => p.getBattlerIndex() === hudState.focus) ?? bosses[0] ?? null;
    const hasBoss = !!this.featuredBoss;

    this.bossPanel.setVisible(hasBoss);
    this.bossText.setVisible(hasBoss);
    this.bossHp.setVisible(hasBoss);
    this.bossFill.setVisible(hasBoss);
    this.bossLevel?.setVisible(hasBoss);

    if (this.featuredBoss) {
      const boss = this.featuredBoss;
      const ratio = Math.max(0, Math.min(1, boss.getHpRatio(true)));
      const rect = SQUAD_HEADER_RECT;
      const trough = this.bossPanel.trough(true);
      const x = rect.x + trough.x;
      const y = rect.y + trough.y;
      this.bossFill
        .setFrame(hpFrame(ratio))
        .setPosition(x, y)
        .setDisplaySize(Math.max(0.5, trough.width * ratio), trough.height)
        .setVisible(ratio > 0);
      drawShield(this.background, boss, { x, y: y + 1, width: trough.width, height: 2 });
      for (let i = 1; i < boss.bossSegments; i++) {
        this.background
          .fillStyle(boss.bossSegmentIndex >= i ? 0xffffff : 0x404040)
          .fillRect(x + (trough.width * i) / boss.bossSegments - 0.5, y, 1, trough.height);
      }
      fitText(
        this.bossText,
        `${boss.getNameToRender()}${bosses.length > 1 ? ` (${bosses.indexOf(boss) + 1}/${bosses.length})` : ""}`,
        rect.width * 0.62,
      );
      this.bossText.setPosition(rect.x + 8, rect.y + 1.5);
      const isMaxLevel = boss.level >= globalScene.getMaxExpLevel();
      const levelKey = `${boss.id}:${boss.level}:${isMaxLevel}`;
      if (levelKey !== this.bossLevelKey) {
        this.bossLevelKey = levelKey;
        this.bossLevel?.destroy();
        this.bossLevel = addLevelBadge(rect.x + rect.width - 30, rect.y + 4, boss.level, 0.5, isMaxLevel).setName("native-boss-level");
        this.add(this.bossLevel);
      }
      const labelArea = this.bossPanel.stripLabelArea();
      this.bossHp.setText(`首领 · 剩余 ${Math.round(ratio * 100)}%`).setPosition(rect.x + labelArea.x + 1, rect.y + labelArea.y - 0.5);
      fitText(this.bossHp, this.bossHp.text, labelArea.width - 2);
    }

    this.drawCommands();

    const supportPokemon = globalScene.getPlayerParty()[4];
    const commandHandler = this.owner.handlers[UiMode.COMMAND] as CommandUiHandler;
    const jiemingCommand = commandHandler.getSquadCommands().find((c) => c.id === 7);

    this.window("support", 4, 134, 79, 11);
    if (supportPokemon !== this.supportIconFor) {
      this.supportIcon?.destroy();
      this.supportIcon = null;
      this.supportIconFor = supportPokemon ?? null;
      if (supportPokemon) {
        const icon = globalScene.addPokemonIcon(supportPokemon, 0, 0, 0.5, 0.5);
        icon
          .setScale(SUPPORT_ICON_SCALE)
          .setPosition(SUPPORT_ICON_X, SUPPORT_ICON_Y - (SUPPORT_ICON_Y_OFFSET * SUPPORT_ICON_SCALE) / 2)
          .setName("native-support-icon");
        this.add(icon);
        this.supportIcon = icon;
      }
    }
    applyTextStyle(this.supportText, jiemingCommand ? TextStyle.WINDOW : TextStyle.SUMMARY_GRAY, 33);
    const cooldown = currentJiemingCooldown() as { pokemonId?: number; remaining: number[] } | undefined;
    const readout = supportCooldownReadout(
      supportPokemon && cooldown?.pokemonId === supportPokemon.id ? cooldown : undefined,
    );
    this.supportCooldown.setText(readout.text).setVisible(!!readout.text).setPosition(SUPPORT_COOLDOWN_X, 136);
    if (readout.text) {
      applyTextStyle(this.supportCooldown, TextStyle.WINDOW, 33);
      this.supportCooldown.setColor(readout.ready ? SUPPORT_COOLDOWN_READY_COLOR : getTextColor(TextStyle.SUMMARY_GRAY, false));
    }
    this.supportText.setPosition(supportPokemon ? SUPPORT_TEXT_X : 8.5, 136);
    fitLabelWidth(
      this.supportText,
      supportPokemon ? `解明 · ${supportPokemon.getNameToRender()}` : "解明位 · 空",
      supportPokemon
        ? SUPPORT_COOLDOWN_X - (readout.text ? this.supportCooldown.displayWidth + 1.5 : 0) - SUPPORT_TEXT_X
        : 70,
    );
    this.supportCursor.setVisible(
      this.owner.getMode() === UiMode.COMMAND && !!jiemingCommand && commandHandler.getCursor() === 7,
    );
    this.renderStatusPanel();

    globalScene.fieldUI.getByName<Phaser.GameObjects.Container>("p5x-turn-order")?.setVisible(true);
  }

  private renderStatusPanel(): void {
    if (!getSquadStatusPanelMode()) {
      this.statusPanel?.setVisible(false);
      this.statusPanelSignature = "";
      return;
    }
    if (!this.statusPanel) {
      const panel = globalScene.add.container(0, -180).setName("native-status-panel");
      const bg = addWindow(4, 4, 312, 172);
      const title = label(10, 7, "", 44, TextStyle.WINDOW_ALT);
      const body = addTextObject(10, 20, "", TextStyle.WINDOW, {
        fontSize: "42px",
        lineSpacing: 2,
        wordWrap: { width: 1740 },
      });
      body.setName("native-status-panel-body");
      const mkButton = (x: number, text: string, onClick: () => void): Phaser.GameObjects.Text => {
        const btn = addTextObject(x, 168, text, TextStyle.WINDOW_ALT, { fontSize: "30px" });
        return btn
          .setName(`native-status-panel-btn-${text}`)
          .setInteractive({ useHandCursor: true })
          .on(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, () => btn.setAlpha(1))
          .on(Phaser.Input.Events.GAMEOBJECT_POINTER_OUT, () => btn.setAlpha(0.75))
          .on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, onClick)
          .setAlpha(0.75);
      };
      const prev = mkButton(10, "◀ 上一只", () => stepSquadStatusUnit(-1));
      const next = mkButton(258, "下一只 ▶", () => stepSquadStatusUnit(1));
      const close = mkButton(178, "关闭", () => closeSquadStatusPanel());
      const hint = label(93, 168, "", 30, TextStyle.WINDOW_ALT);
      panel.add([bg, title, body, prev, next, close, hint]);
      panel.setVisible(false);
      globalScene.ui.add(panel);
      globalScene.ui.bringToTop(panel);
      this.statusPanel = panel;
      this.statusPanelCols = [body];
      this.statusPanelTitle = title;
      this.statusPanelHint = hint;
    }

    const mode = getSquadStatusPanelMode();
    const field = mode === "player"
      ? globalScene.getPlayerField().filter((p) => p && !p.isFainted())
      : globalScene.getEnemyField().filter((p) => p?.scene && p.isOnField() && !p.isFainted());
    const pageSize = 15;
    const total = field.length;
    setSquadStatusPage(Math.max(0, Math.min(getSquadStatusPage(), Math.max(0, total - 1))));
    const page = getSquadStatusPage();
    const pokemon = field[page];
    const lines: string[] = [];

    if (pokemon) {
      lines.push(`◆ ${pokemon.getNameToRender()}`);
      const stages = BATTLE_STATS.filter((s) => pokemon.getStatStage(s) !== 0).map((s) => {
        const value = pokemon.getStatStage(s);
        return `${i18next.t(getStatKey(s))}${value > 0 ? "+" : ""}${value} ${value > 0 ? "▲" : "▼"}`;
      });
      lines.push(`  能力等级：${stages.length ? stages.join("  ") : "没有强化或弱化"}`);
      const indicators = squadStatusIndicators(pokemon);
      if (indicators.length) {
        for (const indicator of indicators) lines.push(`  ${indicator.title}：${indicator.description}`);
      } else {
        lines.push("  （这只当前没有生效中的状态）");
      }
    } else {
      lines.push("当前场上没有单位");
    }

    const scroll = getSquadStatusScroll();
    const pageLines = lines.slice(scroll, scroll + pageSize);
    const signature = `${mode}|${page}|${total}|${pageLines.join("~")}`;
    this.statusPanel.setVisible(true);
    if (signature !== this.statusPanelSignature) {
      this.statusPanelSignature = signature;
      this.statusPanelCols[0]?.setText(pageLines.join("\n"));
      const titleText = mode === "player" ? "我方状态" : "敌方状态";
      this.statusPanelTitle?.setText(titleText);
      this.statusPanelHint?.setText(`${titleText} ${total ? page + 1 : 0}/${total} · 取消键关闭`);
    }
  }

  private window(key: string, x: number, y: number, width: number, height: number): void {
    let panel = this.panels.get(key);
    if (!panel) {
      panel = addSquadWindow(x, y, width, height, SQUAD_FIELD_SCALE).setName(`native-hud-${key}`);
      this.panels.set(key, panel);
      this.add(panel);
      this.sendToBack(panel);
    }
    panel.setSize(width / SQUAD_FIELD_SCALE, height / SQUAD_FIELD_SCALE);
    panel.setVisible(true);
  }

  private drawCommands(): void {
    const commandHandler = this.owner.handlers[UiMode.COMMAND] as CommandUiHandler;
    const commands = commandHandler.getSquadCommands();
    for (const cursor of this.commandCursors.values()) cursor.setVisible(false);
    for (const labelObj of this.commandLabels.values()) labelObj.setVisible(false);
    for (const hit of this.commandHits.values()) hit.disableInteractive();

    if ([UiMode.COMMAND, UiMode.FIGHT, UiMode.MESSAGE].includes(this.owner.getMode())) {
      const view = getSquadInfoView();
      const labelText = view === "none" ? "场地" : view === "field" ? "我方状态" : view === "player" ? "敌方状态" : "关闭";
      this.drawTouchButton(200, labelText, 228, 132, 36, 8, () => cycleSquadInfoView());
    }

    if (this.owner.getMode() === UiMode.FIGHT) {
      this.window("fight-top", 229, 95, 89, 36);
      this.window("fight-bottom", 229, 137, 89, 41);
      this.drawNavigation("返回", Button.CANCEL, 267, 132, 40, 8);
      return;
    }
    if ([UiMode.TARGET_SELECT, UiMode.BALL, UiMode.JIEMING].includes(this.owner.getMode())) {
      if (this.owner.getMode() !== UiMode.TARGET_SELECT) {
        this.drawNavigation("↑", Button.UP, 232, 149, 18, 11);
        this.drawNavigation("↓", Button.DOWN, 253, 149, 18, 11);
      }
      this.drawNavigation("返回", Button.CANCEL, 276, 149, 40, 11);
      this.drawNavigation("确定", Button.ACTION, 276, 165, 40, 11);
      return;
    }
    if (this.owner.getMode() === UiMode.MESSAGE) {
      this.drawNavigation("继续", Button.ACTION, 276, 165, 40, 11);
      return;
    }
    if (this.owner.getMode() !== UiMode.COMMAND) return;

    this.teraIcon.setVisible(false);
    this.window("command-core", 229, 141, 89, 37);
    const coreSlots = [
      { x: 229, y: 141 },
      { x: 273.5, y: 141 },
      { x: 229, y: 159.5 },
      { x: 273.5, y: 159.5 },
    ];
    const core = commands.slice(0, 4);
    let extraIndex = 0;
    for (const command of commands) {
      const slot = core.includes(command) ? coreSlots[core.indexOf(command)] : undefined;
      let x: number;
      let y: number;
      let w: number;
      let h: number;
      const isCursor = commandHandler.getCursor() === command.id;
      if (slot) {
        x = slot.x;
        y = slot.y;
        w = 44.5;
        h = 18.5;
      } else {
        const extra = command.id === 7 ? 0 : extraIndex++;
        x = command.id === 7 ? 4 : 87 + extra * 34.4;
        y = 134;
        w = command.id === 7 ? 79 : 32.4;
        h = 11;
        if (command.id !== 7) this.window(`command-${command.id}`, x, y, w, h);
      }
      let labelObj = this.commandLabels.get(command.id);
      let hit = this.commandHits.get(command.id);
      if (!labelObj) {
        labelObj = label(0, 0, "", slot ? 40 : 30);
        labelObj.setOrigin(slot ? 0 : 0.5, 0.5);
        this.commandLabels.set(command.id, labelObj);
        this.add(labelObj);
      }
      if (command.id === 4) {
        const teraPokemon = globalScene.getPlayerField().find((p) => p?.isActive()) ?? globalScene.getPlayerField()[0];
        this.teraIcon
          .setTexture("button_tera", teraPokemon ? PokemonType[teraPokemon.getTeraType()].toLowerCase() : "fire")
          .setPosition(x + w / 2, y + h / 2)
          .setVisible(true);
        labelObj.setVisible(false);
        let cursor = this.commandCursors.get(command.id);
        if (!cursor) {
          cursor = globalScene.add.image(0, 0, "cursor").setOrigin(0, 0.5).setName(`native-command-cursor-${command.id}`);
          this.commandCursors.set(command.id, cursor);
          this.add(cursor);
        }
        cursor.setScale(0.45).setPosition(x + 1.5, y + h / 2 + 0.5).setVisible(isCursor);
      } else if (command.id !== 7) {
        labelObj.setVisible(true);
        if (slot) {
          fitText(labelObj, command.label, w - 13);
          labelObj.setPosition(x + 10, y + h / 2 + 0.5);
        } else {
          fitText(labelObj, command.label, w - 8);
          labelObj.setPosition(x + w / 2 + 1, y + h / 2);
        }
        let cursor = this.commandCursors.get(command.id);
        if (!cursor) {
          cursor = globalScene.add.image(0, 0, "cursor").setOrigin(0, 0.5).setName(`native-command-cursor-${command.id}`);
          this.commandCursors.set(command.id, cursor);
          this.add(cursor);
        }
        cursor.setScale(slot ? 0.75 : 0.45).setPosition(slot ? x + 3.5 : x + 1.5, y + h / 2 + 0.5).setVisible(isCursor);
      }
      if (!hit) {
        hit = globalScene.add.zone(0, 0, 1, 1).setOrigin(0);
        hit.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, () => commandHandler.activateSquadCommand(command.id));
        this.commandHits.set(command.id, hit);
        this.add(hit);
      }
      hit.setPosition(x, y).setSize(w, h).setInteractive();
    }
  }

  private drawNavigation(text: string, button: Button, x: number, y: number, width: number, height: number): void {
    const key = 100 + button;
    this.window(`navigation-${key}`, x, y, width, height);
    let labelObj = this.commandLabels.get(key);
    let hit = this.commandHits.get(key);
    if (!labelObj) {
      labelObj = label(0, 0, "", 30).setOrigin(0.5);
      this.commandLabels.set(key, labelObj);
      this.add(labelObj);
    }
    labelObj.setText(text).setPosition(x + width / 2, y + height / 2).setVisible(true);
    if (!hit) {
      hit = globalScene.add.zone(0, 0, 1, 1).setOrigin(0);
      hit.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, () => this.owner.processInput(button));
      this.commandHits.set(key, hit);
      this.add(hit);
    }
    hit.setPosition(x, y).setSize(width, height).setInteractive();
  }

  private drawTouchButton(key: number, text: string, x: number, y: number, width: number, height: number, onClick: () => void): void {
    this.window(`touch-${key}`, x, y, width, height);
    let labelObj = this.commandLabels.get(key);
    if (!labelObj) {
      labelObj = label(0, 0, "", 30).setOrigin(0.5);
      this.commandLabels.set(key, labelObj);
      this.add(labelObj);
    }
    labelObj.setText(text).setPosition(x + width / 2, y + height / 2).setVisible(true);
    let hit = this.commandHits.get(key);
    if (!hit) {
      hit = globalScene.add.zone(0, 0, 1, 1).setOrigin(0);
      hit.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, onClick);
      this.commandHits.set(key, hit);
      this.add(hit);
    }
    hit.setPosition(x, y).setSize(width, height).setInteractive();
  }
}

/** 产物 `bhe` = updateSquadBattleHud — 每帧（Ui.update）创建/刷新 squad HUD */
export function updateSquadBattleHud(ui: UI): void {
  let hud = squadHudCache.get(ui);
  if (!usesSquadHud(globalScene.gameMode)) {
    hud?.setVisible(false);
    document.body.classList.remove("squad-battle-input");
    return;
  }
  if (!hud || !hud.scene || hud.parentContainer !== ui) {
    hud?.destroy();
    hud = new SquadBattleHud(ui);
    squadHudCache.set(ui, hud);
    ui.add(hud);
    ui.sendToBack(hud);
  }
  hud.refresh();
  ui.getMessageHandler()?.applySquadBattleLayout();
  document.body.classList.toggle("squad-battle-input", hud.visible);
}
