export class GameOverPhase extends BattlePhase {
  public readonly phaseName = "GameOverPhase";

  private isVictory: boolean;
  private readonly firstRibbons: PokemonSpecies[] = [];

  constructor(isVictory = false) {
    super();

    this.isVictory = isVictory;
  }

  start() {
    super.start();

    globalScene.phaseManager.hideAbilityBar();

    // Failsafe if players somehow skip floor 200 in classic mode
    if (globalScene.gameMode.isClassic && globalScene.currentBattle.waveIndex > 200) {
      this.isVictory = true;
    }

    // Handle Mystery Encounter special Game Over cases
    // Situations such as when player lost a battle, but it isn't treated as full Game Over
    if (
      !this.isVictory
      && globalScene.currentBattle.mysteryEncounter?.onGameOver
      && !globalScene.currentBattle.mysteryEncounter.onGameOver()
    ) {
      // Do not end the game
      return this.end();
    }
    // Otherwise, continue standard Game Over logic

    if (this.isVictory && globalScene.gameMode.isEndless) {
      const genderIndex = globalScene.gameData.gender ?? PlayerGender.UNSET;
      const genderStr = PlayerGender[genderIndex].toLowerCase();
      globalScene.ui.showDialogue(
        i18next.t("miscDialogue:endingEndless", { context: genderStr }),
        i18next.t("miscDialogue:endingName"),
        0,
        () => this.handleGameOver(),
        0,
        fixedInt(3000),
      );
    } else if (this.isVictory || !globalScene.enableRetries || globalScene.gameMode.isPtSoudache) {
      // ▼▼▼ PKRC 魔改 patch: [PT搜打撤] PT 模式不弹重试询问（产物 `else this.isVictory||
      // !E.enableRetries||E.gameMode.isPtSoudache?this.handleGameOver():<重试询问>`）——搜打撤失败即
      // 结算撤离，不允许原地重来，否则「只能前进不能后退」的玩法约束失效 ▲▲▲
      this.handleGameOver();
      // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲
    } else {
      globalScene.ui.showText(i18next.t("battle:retryBattle"), null, () => {
        globalScene.ui.setMode(
          UiMode.CONFIRM,
          () => {
            globalScene.ui.fadeOut(1250).then(() => {
              globalScene.reset();
              globalScene.phaseManager.clearPhaseQueue();
              globalScene.gameData.loadSession(globalScene.sessionSlotId).then(() => {
                globalScene.phaseManager.pushNew("EncounterPhase", true);

                const availablePartyMembers = globalScene.getPokemonAllowedInBattle().length;

                globalScene.phaseManager.pushNew("SummonPhase", 0, true, true);
                if (globalScene.currentBattle.double && availablePartyMembers > 1) {
                  globalScene.phaseManager.pushNew("SummonPhase", 1, true, true);
                }
                if (
                  globalScene.currentBattle.waveIndex > 1
                  && globalScene.currentBattle.battleType !== BattleType.TRAINER
                ) {
                  globalScene.phaseManager.pushNew("CheckSwitchPhase", 0, globalScene.currentBattle.double);
                  if (globalScene.currentBattle.double && availablePartyMembers > 1) {
                    globalScene.phaseManager.pushNew("CheckSwitchPhase", 1, globalScene.currentBattle.double);
                  }
                }

                globalScene.ui.fadeIn(1250);
                this.end();
              });
            });
          },
          () => this.handleGameOver(),
          false,
          0,
          0,
          1000,
        );
      });
    }
  }

  /**
   * Submethod of {@linkcode handleGameOver} that awards ribbons to Pokémon in the player's party based on the current
   * game mode and challenges.
   */
  private awardRibbons(): void {
    let ribbonFlags = 0n;
    for (const challenge of globalScene.gameMode.challenges) {
      const ribbon = challenge.ribbonAwarded;
      if (challenge.value && ribbon) {
        ribbonFlags |= ribbon;
      }
    }

    // TODO: find a better way to handle blocking ribbons and achievements
    // Block other ribbons if flip stats or inverse is active
    const flip_or_inverse = ribbonFlags & (RibbonData.FLIP_STATS | RibbonData.INVERSE);
    // Block other ribbons if passives on `all` is active
    const passives = ribbonFlags & RibbonData.PASSIVE_CHALLENGE;
    if (flip_or_inverse) {
      ribbonFlags = flip_or_inverse;
    } else if (globalScene.gameMode.challenges.some(c => c.id === Challenges.PASSIVES && c.value === 2)) {
      ribbonFlags = passives;
    } else {
      if (globalScene.gameMode.isClassic) {
        ribbonFlags |= RibbonData.CLASSIC;
      }
      if (isNuzlockeChallenge()) {
        ribbonFlags |= RibbonData.NUZLOCKE;
      }
    }
    // Award ribbons to all Pokémon in the player's party that are considered valid
    // for the current game mode and challenges.
    for (const pokemon of globalScene.getPlayerParty()) {
      const species = pokemon.species;
      if (
        checkSpeciesValidForChallenge(
          species,
          globalScene.gameData.getSpeciesDexAttrProps(species, pokemon.getDexAttr()),
          false,
        )
      ) {
        awardRibbonsToSpeciesLine(species.speciesId, ribbonFlags as RibbonFlag);
      }
    }
  }

  // ▼▼▼ PKRC 魔改 patch: [PT搜打撤] 通关流程 4 方法 + continuePtVictoryFlow
  // ============================================================================
  // 产物真身（`dist.modder-backup-*` @2445051 ~ @2456284，`GameOverPhase` 类体内）：
  //   handleGameOver() 开头：
  //     if (E.gameMode.isP5X && E.gameData.carryOutAwakeningStones(this.isVictory),   ← 误读，实际是
  //     E.gameMode.isPtSoudache) { E.gameData.settlePtSoudacheInventory(E.getPlayerParty(), this.isVictory) }
  //     if (E.gameMode.isPtSoudache) {
  //       const A = E.ptSoudacheEarned || 0;
  //       if (!this.isVictory) A > 0 && E.ui.showText(ptSoudacheDeathPenalty, …)      // 死亡扣 PT
  //       else { this.askSavePokemonUsage(A); return }                                // ★提前 return
  //     }
  //   askSavePokemonUsage(s)     @2452814 len=2333
  //   proceedWithVictory(s, i)   @2455166 len=1259
  //   continuePtVictoryFlow(s,i) @2448559 len=853
  //   settlePtSoudacheInventory  @3834340 len=1116（在 GameData，见 pt-soudache-system.ts）
  //
  // ⚠️ 关键结构差异（勿照抄产物位置）：
  //   产物 `start()` 的分支是 `else this.isVictory||!E.enableRetries||E.gameMode.isPtSoudache
  //   ?this.handleGameOver() : <重试询问>` ⇒ **PT 模式永不弹重试询问，直接结算**。
  //   新树 `start()` 无此条件，PT 失败会弹重试框 ⇒ 已在 start() 补 `isPtSoudache` 到正条件里。
  // ============================================================================

  /**
   * 产物 `askSavePokemonUsage(s)` —— 通关前询问「是否花 PT 保存宝可梦使用次数」。
   *
   * @param earned 本局已赚 PT（= `globalScene.ptSoudacheEarned`）
   *
   * 计价：按区间 `a = floor((waveIndex-1)/30)` 取 `PT_SAVE_PRICE_BY_INTERVAL[a]`，
   * 携带保险锁（`BAOXIAN`）的宝可梦**免费**；库存为 `-1` 表示无限次（不计费也不扣）。
   */
  private askSavePokemonUsage(earned: number): void {
    // ▼▼▼ PKRC 魔改 patch: [PT] 存档未初始化兜底（产物 `E.gameData.ptSoudacheData||(console.error(…),E.gameData.applyDailyStarters())`）▲▲▲
    if (!globalScene.gameData.ptSoudacheData) {
      console.error("[PT搜打撤] ptSoudacheData未初始化，正在初始化...");
      globalScene.gameData.applyDailyStarters();
    }
    // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲

    const party = globalScene.getPlayerParty();
    const waveIndex = globalScene.currentBattle.waveIndex;
    const interval = Math.floor((waveIndex - 1) / 30);
    const unitPrice = PT_SAVE_PRICE_BY_INTERVAL[interval] ?? 12000;
    const inventory = globalScene.gameData.ptSoudacheData?.pokemonInventory ?? {};

    // 需付费的（无保险锁 + 库存非无限）
    const needsSave = party.filter((p) => {
      const id = p.species.getRootSpeciesId();
      return inventory[id] !== -1 && !p.getHeldItems().some((i) => i.type.id === PT_INSURANCE_ITEM_ID);
    });
    // 免费的（带保险锁 + 库存非无限）
    const insuredCount = party.filter((p) => {
      const id = p.species.getRootSpeciesId();
      return inventory[id] !== -1 && p.getHeldItems().some((i) => i.type.id === PT_INSURANCE_ITEM_ID);
    }).length;
    const cost = needsSave.length * unitPrice;
    const totalCount = needsSave.length + insuredCount;

    if (totalCount <= 0) {
      this.proceedWithVictory(earned, false);
      return;
    }

    const prompt =
      cost > 0
        ? `是否花费 ${cost} PT 保存当前队伍的 ${totalCount} 只宝可梦次数？\n`
          + `(每只 ${unitPrice} PT，第${interval + 1}区间 保存花费pt会随着区间增加)`
          + (insuredCount > 0 ? `\n其中 ${insuredCount} 只携带保险锁的宝可梦免费保存` : "")
        : `是否保存当前队伍的 ${totalCount} 只宝可梦次数？\n(全部携带保险锁，免费保存)`;

    globalScene.ui.showText(
      `${prompt}\n保存后下次使用将不消耗次数`,
      null,
      () => {
        globalScene.ui.setOverlayMode(UiMode.CONFIRM, () => {
          const currentParty = globalScene.getPlayerParty();
          const inv = globalScene.gameData.ptSoudacheData?.pokemonInventory ?? {};
          const payCount = currentParty.filter((p) => {
            const id = p.species.getRootSpeciesId();
            return inv[id] !== -1 && !p.getHeldItems().some((i) => i.type.id === PT_INSURANCE_ITEM_ID);
          }).length;
          const finalCost = payCount * unitPrice;
          const ownedPt = globalScene.gameData.pt ?? 0;

          debugLog("pt", `[PT搜打撤] 通关保存 - 当前队伍: ${currentParty.length}只, 需保存: ${payCount}只, 花费: ${finalCost}PT`);

          if (ownedPt < finalCost) {
            globalScene.ui.revertMode();
            globalScene.ui.showText(`PT不足！需要 ${finalCost} PT，当前只有 ${ownedPt} PT`, null, () => {
              globalScene.ui.clearText();
              globalScene.ui.setMode(UiMode.MESSAGE).then(() => {
                this.proceedWithVictory(earned, false);
              });
            }, 1500);
            return;
          }

          globalScene.gameData.addPt(-finalCost);
          if (!globalScene.gameData.ptSoudacheData) {
            console.error("[PT搜打撤] ptSoudacheData未初始化！");
            globalScene.ui.revertMode();
            globalScene.ui.setMode(UiMode.MESSAGE).then(() => {
              this.proceedWithVictory(earned, false);
            });
            return;
          }

          // ▼▼▼ PKRC 魔改 patch: [PT] 写入保险锁「彩蛋」标记（产物 `te||_.set(Y,1)`）——被保险锁覆盖的物种结算时额外+1 次
          const pendingMap = new Map<number, number>();
          let savedCount = 0;
          for (const pokemon of currentParty) {
            const id = pokemon.species.getRootSpeciesId();
            const store = globalScene.gameData.ptSoudacheData.pokemonInventory;
            const cur = store[id] ?? 0;
            const insured = pokemon.getHeldItems().some((i) => i.type.id === PT_INSURANCE_ITEM_ID);
            if (cur !== -1) {
              store[id] = (store[id] || 0) + 1;
              savedCount++;
              if (!insured) {
                pendingMap.set(id, 1);
              }
              debugLog(
                "pt",
                `[PT搜打撤] 保存 ${pokemon.species.name} 次数${insured ? "（保险锁，免费，彩蛋：结算时还会再增加一次）" : ""}，当前库存: ${store[id]}`,
              );
            } else {
              debugLog("pt", `[PT搜打撤] ${pokemon.species.name} 为无限次数，无需保存`);
            }
          }
          globalScene.ptSoudachePendingSave = { pokemonMap: pendingMap, ptCost: finalCost };
          globalScene.gameData.saveSystem();
          globalScene.ui.revertMode();
          globalScene.ui.showText(`成功保存 ${savedCount} 只宝可梦的次数！`, null, () => {
            globalScene.ui.clearText();
            this.proceedWithVictory(earned, true);
          }, 1500);
        }, () => {
          globalScene.ui.revertMode();
          globalScene.ui.clearText();
          globalScene.ui.setMode(UiMode.MESSAGE).then(() => {
            this.proceedWithVictory(earned, false);
          });
        });
      },
    );
  }

  /**
   * 产物 `proceedWithVictory(s, i)` —— 胜利结算。
   *
   * @param saved 是否已保存（true 时清 `ptSoudachePendingSave` 临时标记）
   * @param earned 本局赚取的 PT
   *
   * 加成顺序（**不可交换**）：
   *   ① 护符金币 `AMULET_COIN`：每枚 +20%
   *   ② 死战不退 `ptSoudacheNoRetreatMode`：+50%
   *   ③ 命座结算倍率 `applyGainMultiplier(…, partyConstellationGainMultiplier("ptSettle", …))`
   */
  private proceedWithVictory(earned: number, saved: boolean): void {
    if (saved && globalScene.ptSoudachePendingSave) {
      debugLog("pt", "[PT搜打撤] 通关确认，清除临时标记");
      globalScene.ptSoudachePendingSave = null;
    }

    let total = earned;
    if (earned > 0) {
      const amuletCount = globalScene
        .findModifiers((m) => m.type.id === PT_AMULET_COIN_ITEM_ID)
        .reduce((sum: number, m) => sum + m.stackCount, 0);
      if (amuletCount > 0) {
        const bonus = Math.floor(earned * 0.2 * amuletCount);
        total = earned + bonus;
        debugLog("pt", `[PT搜打撤] 通关护符金币加成: ${amuletCount}个 x20% = +${bonus}PT，总计: ${total}PT`);
      }
      if (globalScene.ptSoudacheNoRetreatMode) {
        const bonus = Math.floor(total * 0.5);
        total += bonus;
        debugLog("pt", `[PT搜打撤] 死战不退模式加成: +50% = +${bonus}PT，最终总计: ${total}PT`);
      }
      globalScene.ptSoudacheEarned = total;
      // 🔴 勘误E3：`partyConstellationGainMultiplier` 首参是 `gainKey:string`，取值域
      //   {pt, money, ptSettle}。传错则「财源」类命座加成**静默失效**（不报错、倍率为 1）。
      const withConstellation = applyGainMultiplier(
        total,
        partyConstellationGainMultiplier("ptSettle", playerPartyRootSpecies(), globalScene.gameData?.ptSoudacheData),
      );
      if (withConstellation !== total) {
        debugLog("pt", `[PT搜打撤] 命之座结算加成: ${total} → ${withConstellation}PT`);
      }
      globalScene.gameData.addPt(withConstellation);
      globalScene.gameData.saveSystem();
    }

    globalScene.ptSoudachePassiveEnabled = false;

    const doGameOver = (newClear: boolean) => {
      globalScene.disableMenu = true;
      globalScene.time.delayedCall(1000, () => {
        globalScene.gameMode.hasDynamicBalance
          ? globalScene.gameData.gameStats.ptSoudacheTalentSessionsWon++
          : globalScene.gameData.gameStats.ptSoudacheSessionsWon++;
        const highest = globalScene.ptSoudacheEarned || 0;
        if (highest > globalScene.gameData.gameStats.highestPtEarned) {
          globalScene.gameData.gameStats.highestPtEarned = highest;
        }
        const firstClear = globalScene.validateAchv(achvs.CLASSIC_VICTORY);
        globalScene.validateAchv(achvs.UNEVOLVED_CLASSIC_VICTORY);
        this.continuePtVictoryFlow(newClear, firstClear);
      });
    };

    // ⚠️ 新树 `isLocalServerConnected` 是 `utils/common.ts` 里的 **let 布尔量**，不是函数
    //   （上游既有正确用法见本文件 593 行 / title-phase.ts:341）⇒ 不能加 `()`。
    if (!isLocalServerConnected || !bypassLogin) {
      pokerogueApi.savedata.session
        .newclear({ slot: globalScene.sessionSlotId, isVictory: true, clientSessionId })
        .then((r: boolean) => doGameOver(!!r));
    } else {
      globalScene.gameData.offlineNewClear().then((r: boolean) => doGameOver(r));
    }
  }

  /**
   * 产物 `continuePtVictoryFlow(s, i)` —— 胜利收尾：解锁 → 清理惩戒之壶召唤物 → 淡出 → 结束。
   *
   * @param newClear 是否首通（决定是否给VOUCHER_PREMIUM）
   * @param firstClear 是否经典首通（产物第二个参数 `i`）
   */
  private continuePtVictoryFlow(newClear: boolean, firstClear: boolean): void {
    if (newClear) {
      this.handleUnlocks();
      // ⚠️ 产物此处是 `E.unshiftPhase(new aT(X.VOUCHER_PREMIUM))`（`VoucherPremiumPhase` +
      //   `Unlockables.VOUCHER_PREMIUM`）。**新树上游已无这两个符号**（v1.11.22 重构掉了），
      //   且 `Unlockables` 里搜不到任何 `VOUCHER*` 成员。
      //   新树给首通奖励的既有路径是 `handleGameOver` 里的 `RibbonModifierRewardPhase`
      //   + `handleUnlocks()`（已在上方调用）⇒ 此处**不重复发奖**，
      //   避免与通用链路叠加导致「首通券 ×2」。
    }

    const fadeDuration = 10000;
    audioManager.fadeOutBgm(fadeDuration, true);

    // 清理「惩戒之壶」召唤物：退出本局时须移除，不进历史
    const party = globalScene.getPlayerParty();
    for (let i = party.length - 1; i >= 0; i--) {
      const pokemon = party[i];
      const data = (pokemon as any)?.customPokemonData;
      if (data?.jiehuReleaseOnExit || data?.jiehuShouldRemove) {
        debugLog("pt", `[惩戒之壶] 通关前清理召唤物: ${pokemon.name}`);
        party.splice(i, 1);
        if (pokemon.isOnField()) {
          pokemon.setVisible(false);
          pokemon.hideInfo();
        }
        pokemon.destroy();
      }
    }

    const activeBattlers = globalScene.getField().filter((p) => p?.isActive(true));
    activeBattlers.map((p) => p.hideInfo());

    const trainer = globalScene.currentBattle?.trainer;
    if (trainer) {
      debugLog("pt", "[PT搜打撤] 销毁训练家精灵");
      trainer.setVisible(false);
      trainer.destroy();
      globalScene.currentBattle.trainer = null;
    }

    globalScene.ui.fadeOut(fadeDuration).then(() => {
      activeBattlers.map((p) => p.setVisible(false));
      globalScene.setFieldScale(1, true);
      globalScene.phaseManager.clearPhaseQueue();
      globalScene.ui.clearText();
      // ▼▼▼ PKRC 魔改 patch: [PT] 收尾等价落点（产物 `this.finishGameOver()` —— 新树无同名方法，
      //   等价语义见本文件 `handleGameOver` 胜利分支：清队列 → `PostGameOverPhase` → `this.end()`）▲▲▲
      globalScene.phaseManager.pushNew("PostGameOverPhase", globalScene.sessionSlotId);
      this.end();
      // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲
    });
  }
  // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲

  handleGameOver(): void {
    // ▼▼▼ PKRC 魔改 patch: [PT搜打撤] 结算拦劫（产物 `handleGameOver(){var i;if(E.gameMode.isP5X&&
    // E.gameData.carryOutAwakeningStones(this.isVictory),E.gameMode.isPtSoudache){const A=
    // E.getPlayerParty();E.gameData.settlePtSoudacheInventory(A,this.isVictory)}if(E.gameMode
    // .isPtSoudache){const A=E.ptSoudacheEarned||0;if(!this.isVictory)A>0&&E.ui.showText(
    // ptSoudacheDeathPenalty,…);else{this.askSavePokemonUsage(A);return}}`）▲▲▲
    if (globalScene.gameMode.isP5X) {
      globalScene.gameData.carryOutAwakeningStones(this.isVictory);
    }
    if (globalScene.gameMode.isPtSoudache) {
      globalScene.gameData.settlePtSoudacheInventory(globalScene.getPlayerParty(), this.isVictory);

      const earned = globalScene.ptSoudacheEarned || 0;
      if (!this.isVictory) {
        // 死亡：展示本局 PT 损失提示后清零（不清零会让玩家带着「已赚但没结算」的 PT 撤离）
        if (earned > 0) {
          globalScene.ui.showText(i18next.t("partyUiHandler:ptSoudacheDeathPenalty"), null, () => {
            globalScene.ptSoudacheEarned = 0;
            globalScene.ui.showText("", 0);
          }, 2000);
        }
      } else {
        // 胜利：走保存次数 → 结算链，**提前 return**（不走通用 doGameOver）
        this.askSavePokemonUsage(earned);
        return;
      }
    }
    // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲

    const doGameOver = (newClear: boolean) => {
      globalScene.disableMenu = true;
      globalScene.time.delayedCall(1000, () => {
        let firstClear = false;
        if (this.isVictory) {
          if (globalScene.gameMode.isClassic) {
            firstClear = globalScene.validateAchv(achvs.CLASSIC_VICTORY);
            globalScene.validateAchv(achvs.UNEVOLVED_CLASSIC_VICTORY);
            globalScene.gameData.gameStats.sessionsWon++;
            for (const pokemon of globalScene.getPlayerParty()) {
              this.awardFirstClassicCompletion(pokemon);
              if (pokemon.species.getRootSpeciesId() !== pokemon.species.getRootSpeciesId(true)) {
                this.awardFirstClassicCompletion(pokemon, true);
              }
            }
            this.awardRibbons();
          } else if (globalScene.gameMode.isDaily && newClear) {
            globalScene.gameData.gameStats.dailyRunSessionsWon++;
            globalScene.validateAchv(achvs.DAILY_VICTORY);
          }
        }

        const fadeDuration = this.isVictory ? 10000 : 5000;
        audioManager.fadeOutBgm(fadeDuration);
        const activeBattlers = globalScene.getField().filter(p => p?.isActive(true));
        activeBattlers.map(p => p.hideInfo());
        globalScene.ui.fadeOut(fadeDuration).then(() => {
          activeBattlers.map(a => a.setVisible(false));
          globalScene.setFieldScale(1, true);
          globalScene.phaseManager.clearPhaseQueue();
          globalScene.ui.clearText();

          if (this.isVictory && globalScene.gameMode.isChallenge) {
            globalScene.gameMode.challenges.forEach(c => globalScene.validateAchvs(ChallengeAchv, c));
          }

          const clear = (endCardPhase?: EndCardPhase) => {
            if (this.isVictory && newClear) {
              this.handleUnlocks();

              for (const species of this.firstRibbons) {
                globalScene.phaseManager.unshiftNew("RibbonModifierRewardPhase", modifierTypes.VOUCHER_PLUS, species);
              }
              if (!firstClear) {
                globalScene.phaseManager.unshiftNew("GameOverModifierRewardPhase", modifierTypes.VOUCHER_PREMIUM);
              }
            }
            this.getRunHistoryEntry().then(runHistoryEntry => {
              globalScene.gameData.saveRunHistory(runHistoryEntry, this.isVictory);
              globalScene.phaseManager.pushNew("PostGameOverPhase", globalScene.sessionSlotId, endCardPhase);
              this.end();
            });
          };

          if (this.isVictory && globalScene.gameMode.isClassic) {
            const dialogueKey = "miscDialogue:ending";

            if (globalScene.ui.shouldSkipDialogue(dialogueKey)) {
              const endCardPhase = globalScene.phaseManager.create("EndCardPhase");
              globalScene.phaseManager.unshiftPhase(endCardPhase);
              clear(endCardPhase);
            } else {
              globalScene.ui.fadeIn(500).then(() => {
                const genderIndex = globalScene.gameData.gender ?? PlayerGender.UNSET;
                const genderStr = PlayerGender[genderIndex].toLowerCase();
                // Dialogue has to be retrieved so that the rival's expressions can be loaded and shown via getCharVariantFromDialogue
                const dialogue = i18next.t(dialogueKey, { context: genderStr });
                globalScene.charSprite
                  .showCharacter(
                    `rival_${globalScene.gameData.gender === PlayerGender.FEMALE ? "m" : "f"}`,
                    getCharVariantFromDialogue(dialogue),
                  )
                  .then(() => {
                    globalScene.ui.showDialogue(
                      dialogueKey,
                      globalScene.gameData.gender === PlayerGender.FEMALE
                        ? trainerConfigs[TrainerType.RIVAL].name
                        : trainerConfigs[TrainerType.RIVAL].nameFemale,
                      null,
                      () => {
                        globalScene.ui.fadeOut(500).then(() => {
                          globalScene.charSprite.hide().then(() => {
                            const endCardPhase = globalScene.phaseManager.create("EndCardPhase");
                            globalScene.phaseManager.unshiftPhase(endCardPhase);
                            clear(endCardPhase);
                          });
                        });
                      },
                    );
                  });
              });
            }
          } else {
            clear();
          }
        });
      });
    };

    // If Online, execute apiFetch as intended
    // If Offline, execute offlineNewClear() only for victory, a localStorage implementation of newClear daily run checks
    if (!bypassLogin || isLocalServerConnected) {
      pokerogueApi.savedata.session
        .newclear({
          slot: globalScene.sessionSlotId,
          isVictory: this.isVictory,
          clientSessionId,
        })
        .then(success => doGameOver(!globalScene.gameMode.isDaily || !!success))
        .catch(_err => {
          globalScene.phaseManager.clearPhaseQueue();
          globalScene.phaseManager.unshiftNew("MessagePhase", i18next.t("menu:serverCommunicationFailed"), 2500);
          // force the game to reload after 2 seconds.
          setTimeout(() => {
            window.location.reload();
          }, 2000);
          this.end();
        });
    } else if (this.isVictory) {
      globalScene.gameData.offlineNewClear().then(result => {
        doGameOver(result);
      });
    } else {
      doGameOver(false);
    }
  }

  handleUnlocks(): void {
    if (this.isVictory && globalScene.gameMode.isClassic) {
      if (!globalScene.gameData.unlocks[Unlockables.ENDLESS_MODE]) {
        globalScene.phaseManager.unshiftNew("UnlockPhase", Unlockables.ENDLESS_MODE);
      }
      if (
        globalScene.getPlayerParty().filter(p => p.fusionSpecies).length > 0
        && !globalScene.gameData.unlocks[Unlockables.SPLICED_ENDLESS_MODE]
      ) {
        globalScene.phaseManager.unshiftNew("UnlockPhase", Unlockables.SPLICED_ENDLESS_MODE);
      }
      if (!globalScene.gameData.unlocks[Unlockables.MINI_BLACK_HOLE]) {
        globalScene.phaseManager.unshiftNew("UnlockPhase", Unlockables.MINI_BLACK_HOLE);
      }
      if (
        !globalScene.gameData.unlocks[Unlockables.EVIOLITE]
        && globalScene.getPlayerParty().some(p => speciesDataRegistry.hasEvolutions(p.getSpeciesForm(true).speciesId))
      ) {
        globalScene.phaseManager.unshiftNew("UnlockPhase", Unlockables.EVIOLITE);
      }
    }
  }

  awardFirstClassicCompletion(pokemon: Pokemon, forStarter = false): void {
    const speciesId = getPokemonSpecies(pokemon.species.speciesId);
    const speciesRibbonCount = globalScene.gameData.incrementRibbonCount(speciesId, forStarter);
    // first time classic win, award voucher
    if (speciesRibbonCount === 1) {
      this.firstRibbons.push(getPokemonSpecies(pokemon.species.getRootSpeciesId(forStarter)));
    }
  }

  // TODO: Make function use existing getSessionSaveData() function and then modify the values from there.
  /**
   * Slightly modified version of {@linkcode GameData.getSessionSaveData}.
   * @returns A promise containing the {@linkcode SessionSaveData}
   */
  private async getRunHistoryEntry(): Promise<SessionSaveData> {
    const preWaveSessionData = await globalScene.gameData.getSession(globalScene.sessionSlotId);
    return {
      seed: globalScene.seed,
      playTime: globalScene.sessionPlayTime,
      gameMode: globalScene.gameMode.modeId,
      party: globalScene.getPlayerParty().map(p => new PokemonData(p)),
      enemyParty: globalScene.getEnemyParty().map(p => new PokemonData(p)),
      modifiers: preWaveSessionData
        ? preWaveSessionData.modifiers
        : globalScene.findModifiers(() => true).map(m => new PersistentModifierData(m, true)),
      enemyModifiers: preWaveSessionData
        ? preWaveSessionData.enemyModifiers
        : globalScene.findModifiers(() => true, false).map(m => new PersistentModifierData(m, false)),
      arena: new ArenaData(globalScene.arena),
      pokeballCounts: globalScene.pokeballCounts,
      money: Math.floor(globalScene.money),
      score: globalScene.score,
      waveIndex: globalScene.currentBattle.waveIndex,
      battleType: globalScene.currentBattle.battleType,
      trainer: globalScene.currentBattle.trainer ? new TrainerData(globalScene.currentBattle.trainer) : null,
      gameVersion: globalScene.game.config.gameVersion,
      timestamp: Date.now(),
      challenges: globalScene.gameMode.challenges.map(c => new ChallengeData(c)),
      mysteryEncounterType: globalScene.currentBattle.mysteryEncounter?.encounterType ?? -1,
      mysteryEncounterSaveData: globalScene.mysteryEncounterSaveData,
      playerFaints: globalScene.arena.playerFaints,
    } as SessionSaveData;
  }
}
