import { applyAbAttrs } from "#abilities/apply-ab-attrs";
import { globalScene } from "#app/global-scene";
import { getPokemonNameWithAffix } from "#app/messages";
import { TerrainType } from "#data/terrain";
import { BattlerTagLapseType } from "#enums/battler-tag-lapse-type";
import { WeatherType } from "#enums/weather-type";
import { TurnEndEvent } from "#events/battle-scene";
import type { Pokemon } from "#field/pokemon";
import {
  EnemyStatusEffectHealChanceModifier,
  EnemyTurnHealModifier,
  TurnHealModifier,
  TurnHeldItemTransferModifier,
  TurnStatusEffectModifier,
} from "#modifiers/modifier";
import { FieldPhase } from "#phases/field-phase";
// ▼▼▼ PKRC 魔改 patch: TurnEndPhase（A4-00b 探针）▲▲▲
import { settleP5XRoundEffects } from "#data/systems/p5x-system";
import {
  applyBadDreamsTalentDamage,
  applySleepTurnEndRecovery,
  resetIceAgeTurnData,
  resetIndustrialAgeTurnData,
  resetInfoAgeTurnData,
  resetStoneAgeTurnData,
  resetTotemAgeTurnData,
} from "#data/systems/talent-system";
// ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲
import i18next from "i18next";

export class TurnEndPhase extends FieldPhase {
  public readonly phaseName = "TurnEndPhase";
  public upcomingInterlude = false;

  start() {
    super.start();

    globalScene.currentBattle.incrementTurn();
    globalScene.eventTarget.dispatchEvent(new TurnEndEvent(globalScene.currentBattle.turn));
    globalScene.phaseManager.dynamicQueueManager.clearLastTurnOrder();
    // ▼▼▼ PKRC 魔改 patch: 回合末结算 P5X 效果（产物 `E.gameMode?.isP5X || cw()`）—— P5X 模式下跳过 ▲▲▲
    if (!globalScene.gameMode?.isP5X) {
      settleP5XRoundEffects();
    }
    // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲

    globalScene.phaseManager.hideAbilityBar();

    const handlePokemon = (pokemon: Pokemon) => {
      if (!pokemon.switchOutStatus) {
        pokemon.lapseTags(BattlerTagLapseType.TURN_END);

        globalScene.applyModifiers(TurnHealModifier, pokemon.isPlayer(), pokemon);

        if (globalScene.arena.terrain?.terrainType === TerrainType.GRASSY && pokemon.isGrounded()) {
          globalScene.phaseManager.unshiftNew(
            "PokemonHealPhase",
            pokemon.getBattlerIndex(),
            Math.max(pokemon.getMaxHp() >> 4, 1),
            i18next.t("battle:turnEndHpRestore", {
              pokemonName: getPokemonNameWithAffix(pokemon),
            }),
            true,
          );
        }

        if (!pokemon.isPlayer()) {
          globalScene.applyModifiers(EnemyTurnHealModifier, false, pokemon);
          globalScene.applyModifier(EnemyStatusEffectHealChanceModifier, false, pokemon);
        }

        applyAbAttrs("PostTurnAbAttr", { pokemon });

        // ▼▼▼ PKRC 魔改 patch: 睡眠回合末恢复 + 噩梦天赋伤害（产物 `hue(r),Cue(r)`）▲▲▲
        applySleepTurnEndRecovery(pokemon);
        applyBadDreamsTalentDamage(pokemon);
        // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲
      }

      globalScene.applyModifiers(TurnStatusEffectModifier, pokemon.isPlayer(), pokemon);
      globalScene.applyModifiers(TurnHeldItemTransferModifier, pokemon.isPlayer(), pokemon);

      pokemon.tempSummonData.turnCount++;
      pokemon.tempSummonData.waveTurnCount++;
    };

    if (!this.upcomingInterlude) {
      this.executeForAll(handlePokemon);

      globalScene.arena.lapseTags();
    }

    if (globalScene.arena.weather && !globalScene.arena.weather.lapse()) {
      globalScene.arena.trySetWeather(WeatherType.NONE);
      globalScene.arena.triggerWeatherBasedFormChangesToNormal();
    }

    if (globalScene.arena.terrain && !globalScene.arena.terrain.lapse()) {
      globalScene.arena.trySetTerrain(TerrainType.NONE);
    }

    // ▼▼▼ PKRC 魔改 patch: 年代天赋的「回合数据」重置（产物 5 个 `try{…}catch{}`，原样保留容错）▲▲▲
    try {
      resetIceAgeTurnData();
    } catch {}
    try {
      resetStoneAgeTurnData();
    } catch {}
    try {
      resetIndustrialAgeTurnData();
    } catch {}
    try {
      resetInfoAgeTurnData();
    } catch {}
    try {
      resetTotemAgeTurnData();
    } catch {}
    // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲

    this.end();
  }
}
