/**
 * 产物 `I8` — 乘风（`CHENGFENG`）场域标签。
 * 效果：本方非变化招式伤害 +6；入场时清除地形。
 */
export class ChengfengTag extends SerializableArenaTag {
  public readonly tagType = "CHENGFENG" as SerializableArenaTagType;

  constructor(turnCount: number, sourceId: number, side: ArenaTagSide) {
    // 产物 `super(_e.CHENGFENG, s, undefined, i, A)` ⇒ tagType 提为字段，sourceMove 为 `undefined`
    super(turnCount, undefined, sourceId, side);
  }

  protected override get onAddMessageKey(): string {
    return `arenaTag:chengfengOnAdd${this.i18nSideKey}`;
  }

  protected override get onRemoveMessageKey(): string {
    return `arenaTag:chengfengOnRemove${this.i18nSideKey}`;
  }

  /** 产物 `onAdd(arena, quiet)`：消息由 message-key 承载；此处保留「清除地形」副作用。 */
  public override onAdd(quiet = false): void {
    super.onAdd(quiet);
    const arena = globalScene.arena;
    if (arena.terrain) {
      arena.trySetTerrain(TerrainType.NONE, true);
    }
  }

  /**
   * 产物 `apply(s, i, pokemon, holder, move)` —— 本方非变化招式伤害 +6。
   * ⚠️ 新树 `ArenaTag.apply(...args: unknown[])` 为**变参**，实参由 `arena.applyTags*` 的调用方决定；
   *    该调用点属 **A3 范围缺口**（未迁移）⇒ 此处按产物形参名推断顺序，**补迁时须逐字核对**。
   */
  public override apply(...args: unknown[]): void {
    const [, , pokemon, holder, move] = args as [
      unknown,
      unknown,
      { isPlayer(): boolean } | undefined,
      { value: number } | undefined,
      { category: MoveCategory } | undefined,
    ];
    if (!pokemon || !holder || !move) {
      return;
    }
    if (pokemon.isPlayer() !== (this.side === ArenaTagSide.PLAYER)) {
      return;
    }
    if (move.category !== MoveCategory.STATUS) {
      holder.value += 6;
    }
  }
}

/**
 * 产物 `o8` — 空间房间（`KONGJIAN`）场域标签。
 * 效果：顶替戏法空间；全场重新计算能力；帕路奇亚免疫；本方速度 -6。
 */
export class KONGJIANRoomTag extends SerializableArenaTag {
  public readonly tagType = "KONGJIAN" as SerializableArenaTagType;

  constructor(turnCount: number, sourceId: number) {
    // 产物 `super(_e.KONGJIAN, s, t.KONGJIAN, i)` ⇒ sourceMove = `MoveId.KONGJIAN`
    super(turnCount, MoveId.KONGJIAN, sourceId, ArenaTagSide.BOTH);
  }

  protected override get onAddMessageKey(): string {
    return "arenaTag:kongjianOnAdd";
  }

  protected override get onRemoveMessageKey(): string {
    return "arenaTag:kongjianOnRemove";
  }

  /** 产物 `onAdd(arena)`：顶替戏法空间 + 全场重算能力。 */
  public override onAdd(quiet = false): void {
    super.onAdd(quiet);
    globalScene.arena.removeTag(ArenaTagType.TRICK_ROOM);
    globalScene.getField(true).forEach((p) => p?.calculateStats());
  }

  /** 产物 `onRemove(arena)`：全场重算能力。 */
  public override onRemove(quiet = false): void {
    super.onRemove(quiet);
    globalScene.getField(true).forEach((p) => p?.calculateStats());
  }

  /**
   * 产物 `apply(arena, x, pokemon, holder)` —— 帕路奇亚免疫；否则本方速度 -6。
   * ⚠️ 同 `ChengfengTag.apply`：实参顺序**待补迁时核对**。
   */
  public override apply(...args: unknown[]): void {
    const [, , pokemon, holder] = args as [
      unknown,
      unknown,
      { species?: { speciesId: SpeciesId } } | undefined,
      { value: number } | undefined,
    ];
    if (pokemon?.species?.speciesId === SpeciesId.PALKIA) {
      return;
    }
    if (holder) {
      holder.value -= 6;
    }
  }
}

