/**
 * 产物 `Yk` — 消防员·换人抉择阶段。
 * 触发时询问玩家：「换人」或「随机 +1 能力级」。
 */
export class FirefighterChoicePhase extends Phase {
  public readonly phaseName = "FirefighterChoicePhase";

  constructor(
    public firefighterPokemon: any,
    public attacker: any,
    public targetFieldIndex: number,
    public isPlayerSide: boolean,
  ) {
    super();
  }

  public override start(): void {
    super.start();
    const message = i18next.t("abilityTriggers:firefighterChoice", {
      pokemonName: getPokemonNameWithAffix(this.firefighterPokemon),
      abilityName: i18next.t("ability:firefighter.name"),
    });
    globalScene.ui.showText(message, null, () => {
      globalScene.ui.setMode(UiMode.CONFIRM, () => {
        globalScene.ui.setMode(UiMode.MESSAGE);
        this.firefighterPokemon.__firefighterPending = true;
        const partyIndex = (this.isPlayerSide ? globalScene.getPlayerParty() : globalScene.getEnemyParty()).findIndex(
          (p: any) => p.id === this.firefighterPokemon.id,
        );
        if (partyIndex > -1) {
          globalScene.phaseManager.unshiftPhase(
            // 新树 `SwitchSummonPhase(switchType, fieldIndex, slotIndex, doReturn, player)` —— 5 参与产物一致
            new SwitchSummonPhase(SwitchType.SWITCH, this.targetFieldIndex, partyIndex, true, this.isPlayerSide),
          );
        }
        this.end();
      }, () => {
        globalScene.ui.setMode(UiMode.MESSAGE);
        this.applyRandomStatBoost();
        this.end();
      });
    });
  }

  private applyRandomStatBoost(): void {
    const field = globalScene.getPlayerField().filter((p) => p.isActive());
    if (field.length === 0) {
      return;
    }
    const target = field[randInt(field.length)];
    const stats: BattleStat[] = [Stat.ATK, Stat.DEF, Stat.SPATK, Stat.SPDEF, Stat.SPD];
    const stat = stats[randInt(stats.length)];
    globalScene.phaseManager.unshiftPhase(new StatStageChangePhase(target.getBattlerIndex(), true, [stat], 1));
    globalScene.phaseManager.queueMessage(
      i18next.t("abilityTriggers:firefighterStatBoost", {
        pokemonName: getPokemonNameWithAffix(target),
        statName: i18next.t(`stat:${stat}`),
      }),
    );
  }
}

