// ─────────────────────────────────────────────────────────────

/** 产物 `O1` — 能力翻转（挑战版：整体逆序） */
export class FlipStatChallenge extends Challenge {
  constructor() {
    // 产物 `super(Ut.FLIP_STAT, 1)`；`Ut` = **`Challenges`**（勘误 E12）
    super(Challenges.FLIP_STAT, 1);
  }

  /** 上游已有 `Challenge.applyFlipStat(pokemon, baseStats)` ⇒ 加 `override`。 */
  public override applyFlipStat(_pokemon: any, baseStats: number[]): boolean {
    const snapshot = cloneStatArray(baseStats);
    baseStats[0] = snapshot[5];
    baseStats[1] = snapshot[4];
    baseStats[2] = snapshot[3];
    baseStats[3] = snapshot[2];
    baseStats[4] = snapshot[1];
    baseStats[5] = snapshot[0];
    return true;
  }

  public static override loadChallenge(source: any): FlipStatChallenge {
    const challenge = new FlipStatChallenge();
    challenge.value = source.value;
    challenge.severity = source.severity;
    return challenge;
  }
}

