import { applyAbAttrs } from "#abilities/apply-ab-attrs";
// ▼▼▼ PKRC 魔改 patch: MoveEndPhase（A4-00b 批次 3c）▲▲▲
import { allMoves } from "#data/data-lists";
import { tickJiemingCooldownsByAllyAction } from "#data/systems/jieming-system";
import { trySeaGuardChase } from "#data/systems/manaphy-system";
// ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲
import { globalScene } from "#app/global-scene";
import type { BattlerIndex } from "#enums/battler-index";
import { BattlerTagLapseType } from "#enums/battler-tag-lapse-type";
import type { Pokemon } from "#field/pokemon";
import { PokemonPhase } from "#phases/pokemon-phase";

export class MoveEndPhase extends PokemonPhase {
  public readonly phaseName = "MoveEndPhase";
  /**
   * Whether the current move was a follow-up attack or not.
   * Used to prevent ticking down Encore and similar effects when copying moves.
   */
  private readonly wasFollowUp: boolean;

  /** Targets from the preceding MovePhase */
  private readonly targets: Pokemon[];
  constructor(battlerIndex: BattlerIndex, targets: Pokemon[], wasFollowUp = false) {
    super(battlerIndex);

    this.targets = targets;
    this.wasFollowUp = wasFollowUp;
  }

  start() {
    super.start();

    const pokemon = this.getPokemon();

    // Reset hit-related temporary data.
    // TODO: These properties should be stored inside a "move in flight" object,
    // which this Phase would promptly destroy
    if (pokemon) {
      pokemon.turnData.hitsLeft = -1;
    }

    if (!this.wasFollowUp && pokemon?.isActive(true)) {
      pokemon.lapseTags(BattlerTagLapseType.AFTER_MOVE);
    }

    // ▼▼▼ PKRC 魔改 patch: 招式结束钩子（产物 `zTe(s,r)` / `are()`）▲▲▲
    if (pokemon?.isPlayer()) {
      // 解明「追光」结算（产物 `try{…zTe(s,r)}catch(e){ console.error("[解明] 追光结算失败:",e) }`）
      try {
        const lastMove = pokemon.getLastXMoves(1)[0];
        if (lastMove) {
          const power = allMoves[lastMove.move]?.power ?? 0;
          trySeaGuardChase(pokemon, power);
        }
      } catch (e) {
        console.error("[解明] 追光结算失败:", e);
      }
    }
    // 解明冷却推进（产物 `!isP5X && s.isPlayer() && are()`）
    if (!globalScene.gameMode.isP5X && pokemon?.isPlayer()) {
      tickJiemingCooldownsByAllyAction();
    }
    // ▲▲▲ PKRC 魔改 patch 结束 ▲▲▲

    // Remove effects which were set on a Pokemon which removes them on summon (i.e. via Mold Breaker)
    globalScene.arena.setIgnoreAbilities(false);
    for (const target of this.targets) {
      if (target) {
        applyAbAttrs("PostSummonRemoveEffectAbAttr", { pokemon: target });
      }
    }

    // TODO: Unshift a phase to trigger dancer for all active pokemon if at least 1 has the ability.
    this.end();
  }
}
