/**
 * PKRC 小队 HUD 工具层（A3-补 第二十二批 §5-a）
 * ---------------------------------------------------------------------------
 * 来源：产物 `loading-scene-By2k7Qfx.js`
 *   Ooe  → hpFrame                   （血量条帧名）
 *   Ioe  → drawShield                （解明护盾条）
 *   Ti   → fitText                   （文本缩放到宽度内）
 *   ooe  → addPixelNumbers           （像素数字容器）
 *   Roe  → addLevelBadge             （等级徽章容器）
 *   Kte  → squadPlayerCardRect       （我方卡片槽位矩形）
 *   vIe  → squadEnemyHeadRect        （敌方头顶牌矩形，含避让）
 *   Bhe  → visibleSpriteTop          （精灵可见顶部 y，canvas 逐像素扫描 + WeakMap 缓存）
 *
 * ⚠️ 本批只迁**工具层**（与 UnitCard 本体解耦）；UnitCard（产物 `F2`，4859 字符）与
 *   面板类（产物 `wh`）留待「squad 卡片批」——它们还依赖 `statuses`(ab)/资源指示行(COe)/
 *   applyTextStyle(lB) 等未迁函数，见 §28 挂账。
 */

import { globalScene } from "#app/global-scene";
import type { Pokemon } from "#field/pokemon";

// ─────────────────────────────────────────────────────────────
// 常量（产物 `_he` / `oH` / `Ghe` / `Em` / `aU`）
// ─────────────────────────────────────────────────────────────

/** 护盾条颜色（产物 `_he` = 14252016） */
const SHIELD_COLOR = 0xd98ff0;
/** 护盾条单段宽度（产物 `oH` = 3） */
const SHIELD_SEGMENT_WIDTH = 3;
/** 护盾条段间空隙（产物 `Ghe` = 2） */
const SHIELD_GAP_WIDTH = 2;
/** 敌方头顶牌尺寸（产物 `Em`） */
const ENEMY_CARD_SIZE = { width: 22, height: 10 };
/** 已占用区域（产物 `aU`，头顶牌避让的基准矩形） */
export const SQUAD_HEADER_RECT = { x: 64, y: 0, width: 171, height: 18 };

/** 血量槽几何（产物面板 `trough()` 的返回值形状） */
export interface SquadTrough {
  x: number;
  y: number;
  width: number;
  height: number;
}

// ─────────────────────────────────────────────────────────────
// 工具函数
// ─────────────────────────────────────────────────────────────

/**
 * 产物 `Ooe` — 血量条帧名。
 * 注：上游 battle-info.ts 内为内联三目（`hpFrame` 局部变量），此处提取为可复用函数。
 */
export function hpFrame(ratio: number): string {
  return ratio > 0.5 ? "high" : ratio > 0.25 ? "medium" : "low";
}

/**
 * 产物 `Ioe` — 绘制解明护盾条（分段虚线）。
 * @param graphics 绘制目标
 * @param pokemon 宝可梦（读 `getJiemingShieldRatio?.()`，缺失时按 `jiemingShield / maxHp` 折算）
 * @param trough 血量槽几何
 */
export function drawShield(
  graphics: Phaser.GameObjects.Graphics,
  pokemon: Pokemon,
  trough: SquadTrough,
): void {
  const ratio =
    (pokemon as any).getJiemingShieldRatio?.()
    ?? (pokemon.jiemingShield > 0 ? Math.min(1, pokemon.jiemingShield / pokemon.getMaxHp()) : 0);
  if (ratio <= 0) {
    return;
  }
  const halfHeight = trough.height / 2;
  const filled = Math.max(SHIELD_SEGMENT_WIDTH * halfHeight, trough.width * Math.min(1, ratio));
  const y = trough.y + trough.height / 2;
  graphics.lineStyle(trough.height, SHIELD_COLOR, 1);
  for (
    let offset = 0;
    offset < filled;
    offset += (SHIELD_SEGMENT_WIDTH + SHIELD_GAP_WIDTH) * halfHeight
  ) {
    graphics.lineBetween(
      trough.x + offset,
      y,
      trough.x + Math.min(offset + SHIELD_SEGMENT_WIDTH * halfHeight, filled),
      y,
    );
  }
}

/**
 * 产物 `Ti` — 设置文本并缩放到指定宽度内（放不下时末尾追加 `…`）。
 * 基准比例存在对象自身 `eryouBaseScale` 数据中（产物同款约定）。
 */
export function fitText(
  textObject: Phaser.GameObjects.Text,
  text: string,
  maxWidth: number,
  shrinkRatio = 0.78,
): Phaser.GameObjects.Text {
  const baseScale = textObject.getData("eryouBaseScale") ?? textObject.scaleX;
  textObject.setData("eryouBaseScale", baseScale);
  textObject.setScale(baseScale);
  textObject.setText(text);
  if (textObject.displayWidth <= maxWidth || maxWidth <= 0) {
    return textObject;
  }
  textObject.setScale(Math.max(baseScale * shrinkRatio, (baseScale * maxWidth) / textObject.displayWidth));
  if (textObject.displayWidth <= maxWidth) {
    return textObject;
  }
  const chars = Array.from(text);
  while (chars.length > 1 && textObject.displayWidth > maxWidth) {
    chars.pop();
    textObject.setText(`${chars.join("")}…`);
  }
  return textObject;
}

/**
 * 产物 `ooe` — 用像素数字图集拼出数字串（支持 `/`，红色变体）。
 * @returns 容器（并写入 `pixelWidth` 便于后续排版）
 */
export function addPixelNumbers(
  x: number,
  y: number,
  value: string,
  scale = 0.5,
  align: "left" | "right" = "left",
  red = false,
): Phaser.GameObjects.Container {
  const container = globalScene.add.container(x, y);
  const glyphs = Array.from(value).filter(c => /[0-9/]/.test(c));
  const step = 8 * scale;
  const startX = align === "right" ? -glyphs.length * step : 0;
  glyphs.forEach((glyph, index) => {
    container.add(
      globalScene.add
        .image(startX + index * step, 0, red ? "numbers_red" : "numbers", glyph)
        .setOrigin(0, 0)
        .setScale(scale),
    );
  });
  container.setData("pixelWidth", glyphs.length * step);
  return container;
}

/**
 * 产物 `Roe` — 等级徽章（`overlay_lv` + 像素数字），依赖 {@link addPixelNumbers}。
 */
export function addLevelBadge(
  x: number,
  y: number,
  level: number,
  scale = 0.5,
  red = false,
): Phaser.GameObjects.Container {
  const container = globalScene.add.container(x, y);
  container.add(globalScene.add.image((-3 * scale), 0, "overlay_lv").setOrigin(0, 0).setScale(scale));
  container.add(addPixelNumbers(8 * scale, -0.5 * scale, `${level}`, scale, "left", red));
  return container;
}

/** 产物 `Kte` — 我方小队卡片第 n 槽矩形（6 槽横向 55.5 步进）。 */
export function squadPlayerCardRect(index: number): {
  x: number;
  y: number;
  width: number;
  height: number;
} {
  return { x: 4 + index * 55.5, y: 148, width: 53.5, height: 30 };
}

/**
 * 产物 `vIe` — 敌方头顶牌矩形：夹到可视范围，并对已占用的矩形做向下避让。
 * @param centerX 期望中心 x
 * @param top 期望顶部 y
 * @param occupied 已占用矩形列表（产物 `E.getEnemySpriteHudRects()`）
 */
export function squadEnemyHeadRect(
  centerX: number,
  top: number,
  occupied: readonly { x: number; y: number; width: number; height: number }[] = [],
): { x: number; y: number; width: number; height: number } {
  const { width, height } = ENEMY_CARD_SIZE;
  const minY = SQUAD_HEADER_RECT.y + SQUAD_HEADER_RECT.height + 1;
  const rect = {
    x: Math.max(28, Math.min(320 - width - 2, centerX - width / 2)),
    y: Math.max(minY, Math.min(102, top - height - 6)),
    width,
    height,
  };
  for (const other of occupied) {
    const overlaps =
      rect.x < other.x + other.width + 1
      && rect.x + rect.width > other.x - 1
      && rect.y < other.y + other.height + 1
      && rect.y + rect.height > other.y - 1;
    if (overlaps) {
      rect.y = Math.max(rect.y, other.y + other.height + 2);
    }
  }
  return rect;
}

/** 产物 `Fse` — 精灵顶部扫描结果缓存（WeakMap，按纹理帧） */
const visibleTopCache = new WeakMap<object, number>();

/**
 * 产物 `Bhe` — 求精灵**可见内容顶部**的 y（世界坐标 / 6）。
 * 实现：把纹理帧画到离屏 canvas，从上往下逐像素找第一个不透明行（结果按帧缓存）。
 * ⚠️ 依赖 `document`（浏览器环境）；异常时按产物同款静默返回 0。
 */
export function visibleSpriteTop(sprite: Phaser.GameObjects.Sprite): number {
  const frame = sprite.frame;
  const bounds = sprite.getBounds();
  let offset = visibleTopCache.get(frame as object);
  if (offset === undefined) {
    offset = 0;
    try {
      const canvas = document.createElement("canvas");
      canvas.width = frame.cutWidth;
      canvas.height = frame.cutHeight;
      const ctx = canvas.getContext("2d", { willReadFrequently: true });
      if (ctx) {
        ctx.drawImage(
          frame.source.image as CanvasImageSource,
          frame.cutX,
          frame.cutY,
          frame.cutWidth,
          frame.cutHeight,
          0,
          0,
          frame.cutWidth,
          frame.cutHeight,
        );
        const pixels = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
        search: for (let row = 0; row < canvas.height; row++) {
          for (let col = 0; col < canvas.width; col++) {
            if (pixels[(row * canvas.width + col) * 4 + 3] > 0) {
              offset = row;
              break search;
            }
          }
        }
      }
    } catch {
      // 产物同款静默容错
    }
    visibleTopCache.set(frame as object, offset);
  }
  return (bounds.y + (frame.y + offset) * bounds.height) / Math.max(1, frame.realHeight) / 6;
}

// ─────────────────────────────────────────────────────────────
// 小队卡片面板（A3-补 第二十三批 §5-b）
// ---------------------------------------------------------------------------
// 产物：`fhe` 面板规格表 · `OB` ensureFrame · `m2` 面板类（1476 字符）
//   方法：`rightCap` · `resize` · `trough` · `stripLabelArea` ·
//         `darkHeight` · `panelWidth` · `panelHeight`
// 常量（产物实测）：`Bse`=2 · `yse`=23 · `rH`=9 · `FS`=9 · `SN`=6
// ─────────────────────────────────────────────────────────────

/** 产物常量：九宫格切片/几何阈值 */
const PANEL_SLICE = 2;
const PANEL_FRAME_HEIGHT = 23;
const PANEL_TROUGH_ROW = 9;
const PANEL_FOOT = 9;
const PANEL_LEFT_CAP = 6;

/** 产物 `fhe` — 面板规格（按类型） */
export const SQUAD_PANEL_SPECS = {
  player: {
    key: "pbinfo_player_mini",
    left: 10,
    right: 129,
    troughLeft: 67,
    troughRight: 118,
  },
  enemy: { key: "pbinfo_enemy_mini", left: 0, right: 119, troughLeft: 57, troughRight: 108 },
  boss: { key: "pbinfo_enemy_boss", left: 0, right: 167, troughLeft: 67, troughRight: 156 },
} as const;

export type SquadPanelKind = keyof typeof SQUAD_PANEL_SPECS;

/**
 * 产物 `OB` — 确保纹理中存在指定帧（不存在则按矩形注册并还原 firstFrame）。
 */
export function ensureFrame(
  textureKey: string,
  frameName: string,
  x: number,
  y: number,
  width: number,
  height: number,
): string {
  const texture = globalScene.textures.get(textureKey);
  if (!texture.has(frameName)) {
    const firstFrame = texture.firstFrame;
    texture.add(frameName, 0, x, y, width, height);
    texture.firstFrame = firstFrame;
  }
  return frameName;
}

/**
 * 产物 `m2` — 小队卡片面板（左右两片九宫格 + 血槽几何）。
 * 逐字还原 `constructor/resize/trough/stripLabelArea/darkHeight/panelWidth/panelHeight`。
 */
export class SquadUnitPanel extends Phaser.GameObjects.Container {
  private pixelScale: number;
  private texWidth = 0;
  private texHeight = 0;
  private texLeft = 0;
  private spec: (typeof SQUAD_PANEL_SPECS)[SquadPanelKind];
  private leftPart: Phaser.GameObjects.NineSlice;
  private rightPart: Phaser.GameObjects.NineSlice;

  constructor(kind: SquadPanelKind, width: number, height: number, pixelScale = 1, troughRatio = 0.6) {
    super(globalScene, 0, 0);

    this.pixelScale = pixelScale;
    this.spec = SQUAD_PANEL_SPECS[kind];
    const { key, left, right, troughLeft } = this.spec;
    const leftFrame = ensureFrame(
      key,
      "eryou-left",
      left,
      PANEL_SLICE,
      troughLeft - left,
      PANEL_FRAME_HEIGHT,
    );
    const rightFrame = ensureFrame(
      key,
      "eryou-right",
      troughLeft,
      PANEL_SLICE,
      right - troughLeft + 1,
      PANEL_FRAME_HEIGHT,
    );
    this.leftPart = globalScene.add
      .nineslice(
        0,
        0,
        key,
        leftFrame,
        16,
        18,
        PANEL_LEFT_CAP,
        1,
        PANEL_TROUGH_ROW,
        PANEL_FOOT,
      )
      .setOrigin(0, 0);
    this.rightPart = globalScene.add
      .nineslice(
        0,
        0,
        key,
        rightFrame,
        32,
        18,
        PANEL_SLICE,
        this.rightCap(),
        PANEL_TROUGH_ROW,
        PANEL_FOOT,
      )
      .setOrigin(0, 0);
    this.add([this.leftPart, this.rightPart]);
    this.resize(width, height, troughRatio);
  }

  private rightCap(): number {
    return this.spec.right - this.spec.troughRight + 2;
  }

  resize(width: number, height: number, troughRatio = 0.6): this {
    const scale = this.pixelScale;
    this.texWidth = Math.max(PANEL_LEFT_CAP + 1 + 2 + this.rightCap() + 4, Math.round(width / scale));
    this.texHeight = Math.max(PANEL_TROUGH_ROW + PANEL_FOOT, Math.round(height / scale));
    const minRight = 2 + this.rightCap() + 4;
    const rightWidth = Math.max(minRight, Math.min(this.texWidth - PANEL_LEFT_CAP - 1, Math.round(this.texWidth * troughRatio)));
    this.texLeft = this.texWidth - rightWidth;
    this.leftPart.setSize(this.texLeft, this.texHeight).setScale(scale);
    this.rightPart.setSize(rightWidth, this.texHeight).setScale(scale).setPosition(this.texLeft * scale, 0);
    return this;
  }

  /** 血槽几何（产物 `trough`；`wide` 用于 boss 面板的加高变体） */
  trough(wide = false): SquadTrough {
    const scale = this.pixelScale;
    const width = this.texWidth - this.texLeft - 2 - this.rightCap();
    const height = this.texHeight - PANEL_FOOT + (wide ? 3 : 4);
    return {
      x: (this.texLeft + 2) * scale,
      y: height * scale,
      width: width * scale,
      height: (wide ? 4 : 2) * scale,
    };
  }

  /** 状态/标记条区域（产物 `stripLabelArea`） */
  stripLabelArea(): SquadTrough {
    const scale = this.pixelScale;
    return {
      x: (PANEL_LEFT_CAP + 1) * scale,
      y: (this.texHeight - PANEL_FOOT + 3) * scale,
      width: Math.max(0, this.texLeft - PANEL_LEFT_CAP - 2) * scale,
      height: 4 * scale,
    };
  }

  darkHeight(): number {
    return (this.texHeight - PANEL_FOOT + 2) * this.pixelScale;
  }

  panelWidth(): number {
    return this.texWidth * this.pixelScale;
  }

  panelHeight(): number {
    return this.texHeight * this.pixelScale;
  }
}

// ─────────────────────────────────────────────────────────────
// 文本样式 + 状态指示（A3-补 第二十四批 §5-c）
// ---------------------------------------------------------------------------
// 产物 `lB` = applyTextStyle（setTextStyle + getTextColor + 记录基准缩放）
// 产物 `ab` = statuses（状态 → 海之守护 → 控制抵挡 → P5X 效果 → 自定义指示器）
//   依赖：`findP5XStatusIcon`(qae) · `p5xStatusIconDescription`(zae) ·
//         `getP5XCustomStatusIndicators`(tEe) · Pokemon 字段
//         `seaGuardLayers`/`controlBlockCharges`/`p5xEffects` —— **均已在 src**。
// ─────────────────────────────────────────────────────────────

import { StatusEffect } from "#enums/status-effect";
import { TextStyle } from "#enums/text-style";
import {
  findP5XStatusIcon,
  getP5XCustomStatusIndicators,
  p5xStatusIconDescription,
} from "./p5x-system";
import { addTextObject, getTextColor, setTextStyle } from "#ui/text";

/**
 * 产物 `lB` — 设置文本样式/字号/取色，并把当前缩放记为 `eryouBaseScale`（供 {@link fitText} 用）。
 * ⚠️ 产物的 `Ns(s,!1,E.uiTheme)` 第三参在 src 版 `getTextColor` 中**不存在**（仅 `textStyle, shadow?`）
 *   ⇒ 按 src 签名传两参（第三参在产物里本就是未使用的冗余实参）。
 */
export function applyTextStyle(
  textObject: Phaser.GameObjects.Text,
  style: TextStyle,
  fontSizePx: number,
): Phaser.GameObjects.Text {
  setTextStyle(textObject, style, { fontSize: `${fontSizePx}px` });
  textObject.setColor(getTextColor(style, false));
  textObject.setData("eryouBaseScale", textObject.scaleX);
  return textObject;
}

/** 状态/增益指示项（产物 `ab` 返回的数组元素形状） */
export interface SquadStatusIndicator {
  key: string;
  title: string;
  description: string;
  texture?: string;
  frame?: string | number;
  /** 是否用宝可梦头像做图标（产物 `ownIcon`） */
  ownIcon?: boolean;
}

/**
 * 产物 `ab` — 汇总宝可梦的状态/增益指示项（小队卡片状态行与 tooltip 共用）。
 * 顺序逐字对应：状态 → 海之守护 → 控制抵挡 → P5X 效果 → 自定义指示器。
 */
export function squadStatusIndicators(pokemon: Pokemon): SquadStatusIndicator[] {
  const list: SquadStatusIndicator[] = [];

  const status = pokemon.status;
  if (status?.effect) {
    const frame = StatusEffect[status.effect].toLowerCase();
    const title = ["", "中毒", "剧毒", "麻痹", "睡眠", "冰冻", "灼伤", "倒下"][status.effect] || frame;
    list.push({
      key: "status",
      title,
      description:
        status.effect === StatusEffect.BURN ? `灼伤 ×${(status as any).burnStacks ?? 1}` : title,
      texture: "statuses",
      frame,
    });
  }

  if (pokemon.seaGuardLayers > 0) {
    list.push({ key: "sea-guard", title: "海之守护", description: `${pokemon.seaGuardLayers} 层` });
  }
  if (pokemon.controlBlockCharges > 0) {
    list.push({
      key: "control-block",
      title: "控制抵挡",
      description: `${pokemon.controlBlockCharges} 次`,
    });
  }

  for (const [key, effect] of Object.entries(pokemon.p5xEffects ?? {})) {
    const icon = findP5XStatusIcon(key);
    if (!icon) {
      continue;
    }
    list.push({
      key,
      title: icon.title,
      description: p5xStatusIconDescription(icon, effect),
      texture: icon.texture,
      ownIcon: icon.pokemonIcon === true,
    });
  }

  for (const indicator of getP5XCustomStatusIndicators(pokemon)) {
    list.push({ ...indicator, ownIcon: indicator.pokemonIcon === true });
  }

  return list;
}

// ─────────────────────────────────────────────────────────────
// 资源指示行（A3-补 第二十五批 §5-d）
// ---------------------------------------------------------------------------
// 产物 `COe` = getBattleInfoResourceIndicators
//   预告信（命座>=1 已解锁）→ 潜心（BURST 节点）→ 念力（BASE 节点）→ 生机（healer 可见）
// 别名（keepNames 反查）：q1=callingCardLevelOf · eL=callingCardMaxFor ·
//   XE=chiXinNodeActive · gl=chiXinStacksOf · Gg=chiXinMaxFor ·
//   jr=nianLiNodeActive · D0=nianLiStacksOf · Mg=nianLiMaxFor · qre=healerVigorGaugeState
//   常量：g0=CHIXIN_NODE.BURST(1) · U0=NIANLI_NODE.BASE(1)
// ---------------------------------------------------------------------------

import { callingCardLevelOf, callingCardMaxFor } from "./callingcard-system";
import { CHIXIN_NODE, chiXinMaxFor, chiXinNodeActive, chiXinStacksOf } from "./chixin-system";
import { NIANLI_NODE, nianLiMaxFor, nianLiNodeActive, nianLiStacksOf } from "./nianli-system";
import { healerVigorGaugeState } from "./healer-system";

/**
 * 产物 `COe` — 小队卡片的资源指示行文案（预告信 / 潜心 / 念力 / 生机）。
 * ⚠️ `callingCardLevelOf` 返回**命座等级**（`q1`），`>=1` 即「已解锁预告信体系」；
 *   显示的 `callingCards`/`callingCardMaxFor` 才是层数与上限（见 E14 勘误）。
 */
export function getBattleInfoResourceIndicators(pokemon: Pokemon): string[] {
  const lines: string[] = [];
  if (callingCardLevelOf(pokemon) >= 1) {
    lines.push(`预告信 ${pokemon.customPokemonData?.callingCards ?? 0}/${callingCardMaxFor(pokemon)}`);
  }
  if (chiXinNodeActive(pokemon, CHIXIN_NODE.BURST)) {
    lines.push(`潜心 ${chiXinStacksOf(pokemon)}/${chiXinMaxFor(pokemon)}`);
  }
  if (nianLiNodeActive(pokemon, NIANLI_NODE.BASE)) {
    lines.push(`念力 ${nianLiStacksOf(pokemon)}/${nianLiMaxFor(pokemon)}`);
  }
  const vigor = healerVigorGaugeState(pokemon);
  if (vigor.visible) {
    lines.push(`生机 ${vigor.lit}/${vigor.segments}`);
  }
  return lines;
}

/**
 * 产物 `SB` = describe — 小队卡片的 tooltip 描述文案。
 * Lv/HP → 解明护盾 → 资源指示行（{@link getBattleInfoResourceIndicators}）→ 状态标题（每 4 个一行）。
 */
export function squadDescribe(pokemon: Pokemon): string {
  const lines: string[] = [`Lv.${pokemon.level}   HP ${pokemon.hp}/${pokemon.getMaxHp()}`];
  if (pokemon.jiemingShield > 0) {
    lines.push(`护盾 ${pokemon.jiemingShield}`);
  }
  lines.push(...getBattleInfoResourceIndicators(pokemon));
  const titles = squadStatusIndicators(pokemon).map((indicator) => indicator.title);
  for (let i = 0; i < titles.length; i += 4) {
    lines.push(titles.slice(i, i + 4).join(" · "));
  }
  return lines.join("\n");
}

// ─────────────────────────────────────────────────────────────
// UnitCard 本体（A3-补 第二十五批 §5-e）
// ---------------------------------------------------------------------------
// 产物 `F2` — 小队卡片（我方卡片 / 敌方头顶牌），依赖工具层全部函数。
// 别名：oE=label · F=TextStyle · V=UiMode · fl=setP5XTurnOrderFocus ·
//   SB=describe · R=PokemonType · xn=getLocalizedSpriteKey · l=keepNames(去掉)
// 新树 API 差异：getTypes({includeTeraType}) · getSprite().getWorldTransformMatrix()
// ---------------------------------------------------------------------------

import { PokemonType } from "#enums/pokemon-type";
import { UiMode } from "#enums/ui-mode";
import { getLocalizedSpriteKey } from "#utils/common";
import { setP5XTurnOrderFocus } from "./p5x-turn-order";
import type { TargetSelectUiHandler } from "#ui/handlers/target-select-ui-handler";

/** 产物 `oE` = label — 文本标签（addTextObject + 字号 + origin(0)） */
export function label(
  x: number,
  y: number,
  content = "",
  fontSize = 36,
  style: TextStyle = TextStyle.WINDOW,
): Phaser.GameObjects.Text {
  return addTextObject(x, y, content, style, { fontSize: `${fontSize}px` }).setOrigin(0);
}

/**
 * 产物 `F2` = UnitCard — 小队卡片（我方卡片 / 敌方头顶牌）。
 * 逐字还原 constructor + render（含点击选中目标 / tooltip / 状态行 / 资源行）。
 */
export class SquadUnitCard extends Phaser.GameObjects.Container {
  /** 卡片对应的宝可梦（SquadBattleHud.refresh 需比对对象是否变更 ⇒ public） */
  public readonly pokemon: Pokemon;
  private readonly playerCard: boolean;
  private readonly width_: number;
  private readonly height_: number;
  private readonly panel: SquadUnitPanel;
  private readonly graphics: Phaser.GameObjects.Graphics;
  private readonly hpFill: Phaser.GameObjects.Image;
  private readonly focus: Phaser.GameObjects.Image;
  private readonly title: Phaser.GameObjects.Text;
  private readonly marker: Phaser.GameObjects.Text;
  private readonly stateCount: Phaser.GameObjects.Text;
  private readonly resource: Phaser.GameObjects.Text;
  private readonly statusRow: Phaser.GameObjects.Container;
  private readonly typeRow: Phaser.GameObjects.Container;
  private readonly portrait: Phaser.GameObjects.Container | null;
  private hpNumbers: Phaser.GameObjects.Container | null;
  private levelBadge: Phaser.GameObjects.Container | null;
  private statusSignature = "";
  private typeSignature = "";
  private hpSignature = "";
  private levelSignature = "";

  constructor(pokemon: Pokemon, playerCard: boolean) {
    super(globalScene, 0, 0);
    this.pokemon = pokemon;
    this.playerCard = playerCard;
    this.stateCount = label(0, 0, "", 26);
    this.resource = label(0, 0, "", 26);
    this.hpNumbers = null;
    this.levelBadge = null;
    this.setName(`squad-${playerCard ? "player" : "enemy"}-${pokemon.id}`);

    const playerRect = squadPlayerCardRect(0);
    this.width_ = playerCard ? playerRect.width : ENEMY_CARD_SIZE.width;
    this.height_ = playerCard ? playerRect.height : ENEMY_CARD_SIZE.height;
    this.panel = playerCard
      ? new SquadUnitPanel("player", this.width_, this.height_, 1, 0.64)
      : new SquadUnitPanel("enemy", this.width_, this.height_, 0.5, 0.72);
    this.panel.setName("native-unit-window");

    this.graphics = globalScene.add.graphics();
    this.hpFill = globalScene.add.image(0, 0, "overlay_hp", "high").setOrigin(0).setName("native-hp-bar");
    this.focus = globalScene.add.image(0, 0, "cursor").setOrigin(0, 0.5).setScale(0.45).setName("native-unit-cursor");
    this.title = label(0, 0, "", playerCard ? 40 : 27, TextStyle.BATTLE_INFO);
    this.marker = label(0, 0, "", 24, TextStyle.WINDOW_ALT);
    this.statusRow = globalScene.add.container(0, 0);
    this.typeRow = globalScene.add.container(0, 0);
    this.portrait = playerCard ? globalScene.addPokemonIcon(pokemon, 12, 1, 0.5, 0) : null;
    if (this.portrait) {
      this.portrait.setScale(0.5);
    }

    this.add([
      this.panel,
      this.hpFill,
      this.graphics,
      this.title,
      this.marker,
      this.stateCount,
      this.statusRow,
      this.typeRow,
      this.resource,
      this.focus,
    ]);
    if (this.portrait) {
      this.add(this.portrait);
    }

    this.setInteractive(
      new Phaser.Geom.Rectangle(0, 0, this.width_, this.height_),
      Phaser.Geom.Rectangle.Contains,
    );
    this.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, () => {
      if (globalScene.ui.getMode() === UiMode.TARGET_SELECT) {
        (globalScene.ui.handlers[UiMode.TARGET_SELECT] as TargetSelectUiHandler).selectSquadTarget(pokemon);
      } else {
        setP5XTurnOrderFocus(pokemon);
        globalScene.ui.showTooltip(pokemon.getNameToRender(), squadDescribe(pokemon), true);
      }
    });
    this.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, () =>
      globalScene.ui.showTooltip(pokemon.getNameToRender(), squadDescribe(pokemon), true),
    );
    this.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OUT, () => globalScene.ui.hideTooltip());
  }

  render(active: boolean, hovered: boolean, slotIndex: number): void {
    const pokemon = this.pokemon;
    const width = this.width_;
    const isBoss = !pokemon.isPlayer() && pokemon.isBoss();
    this.graphics.clear();
    this.focus.setVisible(active || hovered);

    const hpRatio = Math.max(0, Math.min(1, pokemon.getHpRatio(true)));
    const trough = this.panel.trough();
    this.hpFill
      .setFrame(hpFrame(hpRatio))
      .setPosition(trough.x, trough.y)
      .setDisplaySize(Math.max(0.5, trough.width * hpRatio), trough.height)
      .setVisible(hpRatio > 0);
    drawShield(this.graphics, pokemon, trough);

    const fainted = pokemon.isFainted();
    if (this.playerCard) {
      const rect = squadPlayerCardRect(slotIndex);
      this.setPosition(rect.x, rect.y - (active ? 2 : 0));
      this.focus.setPosition(-2.5, 9);
      fitText(this.title, pokemon.getNameToRender(), width - 27);
      this.title.setPosition(22, 1.5);
      this.title.setAlpha(fainted ? 0.55 : 1);

      const hpText = `${pokemon.hp}/${pokemon.getMaxHp()}`;
      if (hpText !== this.hpSignature) {
        this.hpSignature = hpText;
        this.hpNumbers?.destroy();
        const scale = Math.min(0.5, (width - 27) / (Array.from(hpText).length * 8));
        this.hpNumbers = addPixelNumbers(22, 9.5, hpText, scale).setName("native-hp-numbers");
        this.add(this.hpNumbers);
      }

      const maxLevel = pokemon.level >= globalScene.getMaxExpLevel();
      const levelSig = `${pokemon.level}:${maxLevel}`;
      if (levelSig !== this.levelSignature) {
        this.levelSignature = levelSig;
        this.levelBadge?.destroy();
        this.levelBadge = addLevelBadge(4, 17.5, pokemon.level, 0.5, maxLevel).setName("native-level");
        this.add(this.levelBadge);
      }

      const labelArea = this.panel.stripLabelArea();
      this.marker.setText(fainted ? "倒下" : active ? "行动中" : "").setPosition(labelArea.x, labelArea.y - 0.5);
      fitText(this.marker, this.marker.text, labelArea.width);
      this.statusRow.setPosition(22, 16);
      this.portrait?.setAlpha(fainted ? 0.3 : 1);
    } else {
      const matrix = pokemon.getSprite().getWorldTransformMatrix();
      const rect = squadEnemyHeadRect(
        matrix.tx / 6,
        visibleSpriteTop(pokemon.getSprite()),
        globalScene.getEnemySpriteHudRects(),
      );
      this.setPosition(rect.x, rect.y);
      this.focus.setPosition(-2.8, 3.2);

      const types = pokemon.getTypes({ includeTeraType: true }).slice(0, 2);
      applyTextStyle(this.title, isBoss ? TextStyle.SUMMARY_GOLD : TextStyle.BATTLE_INFO, 27);
      fitText(this.title, isBoss ? "◆ 首领" : pokemon.getNameToRender(), width - 3.5 - types.length * 3.4);
      this.title.setPosition(2.2, 0.4);
      this.marker.setText("");
      this.statusRow.setPosition(0.5, this.height_ + 0.6);

      const typeSig = types.join(",");
      if (typeSig !== this.typeSignature) {
        this.typeSignature = typeSig;
        this.typeRow.removeAll(true);
        types.forEach((type, index) => {
          const icon = globalScene.add.sprite(
            width - 2.6 - index * 3.4,
            2.4,
            "pbinfo_enemy_type",
            PokemonType[type].toLowerCase(),
          );
          icon.setDisplaySize(3.2, 3.2);
          this.typeRow.add(icon);
        });
      }
    }

    const indicators = squadStatusIndicators(pokemon);
    const statusSig = indicators.map(ind => `${ind.key}:${ind.description}`).join("|");
    const maxStatus = this.playerCard ? 3 : 2;
    if (statusSig !== this.statusSignature) {
      this.statusSignature = statusSig;
      this.statusRow.removeAll(true);
      let offset = 0;
      indicators.slice(0, maxStatus).forEach(ind => {
        let icon: Phaser.GameObjects.Sprite | Phaser.GameObjects.Container | Phaser.GameObjects.Text;
        let advance = 5.5;
        if (ind.ownIcon) {
          icon = globalScene.addPokemonIcon(pokemon, offset + 2, 0, 0.5, 0);
          icon.setScale(0.15);
        } else if (ind.texture === "statuses") {
          const localizedKey = getLocalizedSpriteKey("statuses");
          icon = globalScene.add
            .sprite(offset, 0.2, globalScene.textures.exists(localizedKey) ? localizedKey : "statuses", ind.frame)
            .setOrigin(0)
            .setScale(0.45);
          advance = (icon as Phaser.GameObjects.Sprite).displayWidth + 1.2;
        } else if (ind.texture && globalScene.textures.exists(ind.texture)) {
          icon = globalScene.add.sprite(offset + 2, 2, ind.texture, ind.frame);
          icon.setDisplaySize(4, 4);
        } else {
          icon = label(offset, 0, "◇", 24);
        }
        const showThis = () => globalScene.ui.showTooltip(ind.title, ind.description, true);
        icon.setInteractive(new Phaser.Geom.Rectangle(0, 0, 6, 6), Phaser.Geom.Rectangle.Contains);
        icon.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, showThis);
        icon.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, showThis);
        this.statusRow.add(icon);
        offset += advance;
      });
      this.statusRow.setData("rowWidth", offset);
    }

    const rowWidth = (this.statusRow.getData("rowWidth") as number | undefined) ?? 0;
    const extraCount = indicators.length - maxStatus;
    this.stateCount
      .setText(extraCount > 0 ? `+${extraCount}` : "")
      .setPosition(this.statusRow.x + rowWidth + 0.5, this.statusRow.y - 0.5);

    if (this.playerCard) {
      const resourceX = this.statusRow.x + rowWidth + (extraCount > 0 ? 6 : 0.5);
      this.resource.setPosition(resourceX, this.statusRow.y - 0.5);
      fitText(this.resource, getBattleInfoResourceIndicators(pokemon).join(" · "), width - 4 - resourceX);
    } else {
      this.resource.setText("");
    }
  }
}
